import type { BankQuestion } from "@/lib/bank";

/** DBMS and SQL (CS Fundamentals): 127 questions. Append new ones at the end with the next id; never reuse or renumber an id. */
const questions: BankQuestion[] = [
  {"id":"cs-dbms-sql-1","question":"Which pair of properties must every primary key satisfy?","options":["Unique and NOT NULL","Unique and indexed as clustered","Unique and referenced by a foreign key","NOT NULL and numeric"],"answer":0,"explanation":"A primary key identifies each row, so its values must be unique and can never be NULL. It need not be numeric or clustered, and nothing has to reference it.","difficulty":"easy","source":"TCS NQT · Infosys pattern"},
  {"id":"cs-dbms-sql-2","question":"Which ACID property guarantees that a transaction's changes are applied completely or not at all?","options":["Isolation","Atomicity","Durability","Consistency"],"answer":1,"explanation":"Atomicity is all-or-nothing: if the transaction fails midway, the recovery manager undoes its partial changes. Durability is about committed changes surviving crashes.","difficulty":"easy","source":"Wipro · Cognizant pattern"},
  {"id":"cs-dbms-sql-3","question":"Which of these SQL commands is a DDL (Data Definition Language) command?","options":["INSERT","UPDATE","ALTER","SELECT"],"answer":2,"explanation":"DDL commands define or change structure: CREATE, ALTER, DROP, TRUNCATE, RENAME. INSERT and UPDATE are DML; SELECT is a query (DQL/DML).","difficulty":"easy","source":"TCS NQT · Infosys pattern"},
  {"id": "cs-dbms-sql-4", "question": "In an ER model, a weak entity set is identified by:", "options": ["A composite of all its attributes", "A foreign key to any entity set", "Its own primary key alone", "Its partial key (discriminator) together with the primary key of its owner (identifying) entity set"], "answer": 3, "explanation": "A weak entity has no key of its own; its discriminator becomes unique only when combined with the owner's primary key through the identifying relationship.", "difficulty": "easy", "source": "Accenture · Capgemini pattern"},
  {"id": "cs-dbms-sql-5", "question": "Which SQL clause filters groups AFTER aggregation?", "options": ["HAVING", "WHERE", "GROUP BY", "ORDER BY"], "answer": 0, "explanation": "WHERE filters individual rows before grouping and cannot use aggregates; HAVING filters the groups formed by GROUP BY and can test COUNT, SUM, AVG and so on.", "difficulty": "easy", "source": "Wipro · Cognizant pattern"},
  {"id":"cs-dbms-sql-6","question":"Which statement about the SQL command TRUNCATE TABLE is correct?","options":["It removes rows matching a WHERE clause","It removes all rows but keeps the table structure","It removes the table definition along with its data","It only removes rows whose columns are NULL"],"answer":1,"explanation":"TRUNCATE empties the table and keeps its structure; DROP removes the table itself; DELETE can remove selected rows with WHERE.","difficulty":"easy","source":"HCL · Tech Mahindra pattern"},
  {"id":"cs-dbms-sql-7","question":"Table Emp(id, name, dept, salary, mgr) rows: (1, 'Asha', 'HR', 50000, NULL), (2, 'Ravi', 'IT', 70000, 1), (3, 'Meena', 'IT', 70000, 2), (4, 'John', 'Sales', 40000, 1), (5, 'Kiran', 'IT', 90000, 2), (6, 'Dev', NULL, 45000, 4), (7, 'Lata', 'Sales', NULL, 4).\nTable Dept(dname, city) rows: ('HR', 'Pune'), ('IT', 'Delhi'), ('Ops', 'Mumbai').\nWhat does this query return?\n```sql\nSELECT COUNT(*), COUNT(dept), COUNT(DISTINCT dept)\nFROM Emp;\n```","options":["6, 6, 3","7, 6, 4","7, 6, 3","7, 7, 4"],"answer":2,"explanation":"COUNT(*) counts all 7 rows. COUNT(dept) skips Dev's NULL: 6. COUNT(DISTINCT dept) counts HR, IT, Sales = 3; NULL is not counted as a distinct value.","difficulty":"moderate","source":"TCS NQT · Infosys pattern"},
  {"id": "cs-dbms-sql-8", "question": "Table Emp(id, name, dept, salary, mgr) rows: (1, 'Asha', 'HR', 50000, NULL), (2, 'Ravi', 'IT', 70000, 1), (3, 'Meena', 'IT', 70000, 2), (4, 'John', 'Sales', 40000, 1), (5, 'Kiran', 'IT', 90000, 2), (6, 'Dev', NULL, 45000, 4), (7, 'Lata', 'Sales', NULL, 4).\nTable Dept(dname, city) rows: ('HR', 'Pune'), ('IT', 'Delhi'), ('Ops', 'Mumbai').\nHow many rows does this query return?\n```sql\nSELECT e.name, d.city\nFROM Emp e INNER JOIN Dept d ON e.dept = d.dname;\n```", "options": ["7", "3", "6", "4"], "answer": 3, "explanation": "Matches: Asha (HR) and Ravi, Meena, Kiran (IT) = 4. Sales has no row in Dept, Dev's NULL dept matches nothing, and Ops has no employees.", "difficulty": "moderate", "source": "Wipro · Cognizant pattern"},
  {"id": "cs-dbms-sql-9", "question": "Two tables have 6 rows and 4 rows. How many rows does `SELECT * FROM A, B;` (no WHERE clause) return?", "options": ["24", "6", "10", "4"], "answer": 0, "explanation": "A comma join without a condition is a Cartesian product: 6 × 4 = 24 rows. 10 would be a UNION ALL of the two tables.", "difficulty": "easy", "source": "TCS NQT · Infosys pattern"},
  {"id":"cs-dbms-sql-10","question":"A relation is in 2NF if it is in 1NF and:","options":["It has no multivalued dependency","No non-prime attribute is functionally dependent on a proper subset of any candidate key","Every determinant is a candidate key","It has no transitive dependency of a non-prime attribute on a key"],"answer":1,"explanation":"2NF removes partial dependencies. Removing transitive dependencies gives 3NF; 'every determinant is a candidate key' is BCNF; multivalued dependencies are 4NF.","difficulty":"easy","source":"Accenture · Capgemini pattern"},
  {"id":"cs-dbms-sql-11","question":"R(A, B, C, D) has functional dependencies A → B and B → C. What is the candidate key of R?","options":["ABD","A","AD","AB"],"answer":2,"explanation":"A⁺ = {A, B, C}, which misses D. D appears on no right-hand side, so it must be in every key; (AD)⁺ = {A, B, C, D}. ABD is a superkey but not minimal.","difficulty":"moderate","source":"Wipro · Cognizant pattern"},
  {"id":"cs-dbms-sql-12","question":"Which statement about a clustered index is correct?","options":["A clustered index never speeds up range queries","A table can have any number of clustered indexes","A clustered index must be on a non-key column","A table can have at most one clustered index, because the rows can be physically ordered in only one way"],"answer":3,"explanation":"A clustered index fixes the physical order of rows (or leaf pages) by its key, so only one is possible. Range queries benefit most, since matching rows are stored together.","difficulty":"moderate","source":"HCL · Tech Mahindra pattern"},
  {"id":"cs-dbms-sql-13","question":"Table Emp(id, name, dept, salary, mgr) rows: (1, 'Asha', 'HR', 50000, NULL), (2, 'Ravi', 'IT', 70000, 1), (3, 'Meena', 'IT', 70000, 2), (4, 'John', 'Sales', 40000, 1), (5, 'Kiran', 'IT', 90000, 2), (6, 'Dev', NULL, 45000, 4), (7, 'Lata', 'Sales', NULL, 4).\nTable Dept(dname, city) rows: ('HR', 'Pune'), ('IT', 'Delhi'), ('Ops', 'Mumbai').\nHow many rows do the two queries return?\n```sql\n-- Query 1\nSELECT dept FROM Emp UNION SELECT dname FROM Dept;\n-- Query 2\nSELECT dept FROM Emp UNION ALL SELECT dname FROM Dept;\n```","options":["5 and 10","4 and 9","4 and 10","5 and 9"],"answer":0,"explanation":"UNION ALL keeps everything: 7 + 3 = 10. UNION removes duplicates and treats the NULLs as one value: {NULL, HR, IT, Sales, Ops} = 5. Forgetting that NULL survives as a row gives 4.","difficulty":"moderate","source":"TCS NQT · Infosys pattern"},
  {"id":"cs-dbms-sql-14","question":"Transaction T2 reads a value that T1 has written but not yet committed; T1 later rolls back. What is this anomaly called?","options":["Non-repeatable read","Dirty read","Lost update","Phantom read"],"answer":1,"explanation":"Reading uncommitted data is a dirty read; READ COMMITTED and above prevent it. A non-repeatable read reads committed data that changes between two reads.","difficulty":"easy","source":"Wipro · Cognizant pattern"},
  {"id":"cs-dbms-sql-15","question":"Table Emp(id, name, dept, salary, mgr) rows: (1, 'Asha', 'HR', 50000, NULL), (2, 'Ravi', 'IT', 70000, 1), (3, 'Meena', 'IT', 70000, 2), (4, 'John', 'Sales', 40000, 1), (5, 'Kiran', 'IT', 90000, 2), (6, 'Dev', NULL, 45000, 4), (7, 'Lata', 'Sales', NULL, 4).\nWhich names does this query return?\n```sql\nSELECT name FROM Emp WHERE name LIKE '_a%';\n```","options":["Ravi, Meena, Lata, Kiran","Asha, Meena, Lata","Ravi, Lata","Asha, Ravi, Lata"],"answer":2,"explanation":"_ matches exactly one character and % any number, so the second letter must be 'a': Ravi and Lata. Kiran's 'a' is fourth; names ending in 'a' would need '%a'.","difficulty":"moderate","source":"HCL · Tech Mahindra pattern"},
  {"id":"cs-dbms-sql-16","question":"A candidate key is best described as:","options":["Any set of attributes that uniquely identifies a tuple","An attribute that references another table's key","The key chosen by the designer to identify rows","A minimal superkey: no proper subset of it is a superkey"],"answer":3,"explanation":"A superkey identifies tuples uniquely; a candidate key is a superkey with nothing removable. The one chosen among candidate keys is the primary key; a referencing attribute is a foreign key.","difficulty":"easy","source":"Accenture · Capgemini pattern"},
  {"id":"cs-dbms-sql-17","question":"In an ER diagram, entity sets Student and Course are related by a many-to-many relationship Enrols that has an attribute grade. What is the minimum number of tables needed?","options":["3","1","2","4"],"answer":0,"explanation":"M:N needs its own table holding both keys and grade, plus one table for each entity: 3. Only 1:N or 1:1 relationships can be folded into an entity's table.","difficulty":"moderate","source":"TCS NQT · Infosys pattern"},
  {"id":"cs-dbms-sql-18","question":"Table Emp(id, name, dept, salary, mgr) rows: (1, 'Asha', 'HR', 50000, NULL), (2, 'Ravi', 'IT', 70000, 1), (3, 'Meena', 'IT', 70000, 2), (4, 'John', 'Sales', 40000, 1), (5, 'Kiran', 'IT', 90000, 2), (6, 'Dev', NULL, 45000, 4), (7, 'Lata', 'Sales', NULL, 4).\nTable Dept(dname, city) rows: ('HR', 'Pune'), ('IT', 'Delhi'), ('Ops', 'Mumbai').\nHow many rows does this query return?\n```sql\nSELECT e.name, d.city\nFROM Emp e LEFT JOIN Dept d ON e.dept = d.dname;\n```","options":["8","7","5","4"],"answer":1,"explanation":"A LEFT JOIN keeps every Emp row: the 4 matches plus John, Lata (Sales, no Dept row) and Dev (NULL dept) with city NULL = 7. Ops is dropped because it is on the right side.","difficulty":"moderate","source":"Wipro · Cognizant pattern"},
  {"id":"cs-dbms-sql-19","question":"Which mechanism does a DBMS mainly rely on to guarantee durability of committed transactions?","options":["Normalisation","Locking","Write-ahead logging, with log records forced to stable storage at commit","Indexing"],"answer":2,"explanation":"Under WAL, the commit record and the transaction's log records reach stable storage before commit is acknowledged, so the changes can be redone after a crash. Locking provides isolation.","difficulty":"easy","source":"IBM · Deloitte pattern"},
  {"id":"cs-dbms-sql-20","question":"Table Emp(id, name, dept, salary, mgr) rows: (1, 'Asha', 'HR', 50000, NULL), (2, 'Ravi', 'IT', 70000, 1), (3, 'Meena', 'IT', 70000, 2), (4, 'John', 'Sales', 40000, 1), (5, 'Kiran', 'IT', 90000, 2), (6, 'Dev', NULL, 45000, 4), (7, 'Lata', 'Sales', NULL, 4).\nHow many rows does this query return?\n```sql\nSELECT dept, COUNT(*) FROM Emp GROUP BY dept;\n```","options":["7","3","6","4"],"answer":3,"explanation":"Groups: HR, IT, Sales and one group for NULL (Dev). GROUP BY puts all NULLs in a single group even though NULL = NULL is not true in a WHERE clause.","difficulty":"moderate","source":"Product-company MCQ pattern"},
  {"id": "cs-dbms-sql-21", "question": "Table Emp(id, name, dept, salary, mgr) rows: (1, 'Asha', 'HR', 50000, NULL), (2, 'Ravi', 'IT', 70000, 1), (3, 'Meena', 'IT', 70000, 2), (4, 'John', 'Sales', 40000, 1), (5, 'Kiran', 'IT', 90000, 2), (6, 'Dev', NULL, 45000, 4), (7, 'Lata', 'Sales', NULL, 4).\nWhat does this query return?\n```sql\nSELECT dept FROM Emp\nGROUP BY dept\nHAVING AVG(salary) > 50000;\n```", "options": ["IT", "IT and Sales", "IT and HR", "IT, HR and Sales"], "answer": 0, "explanation": "Averages: HR 50000 (not > 50000), IT (70000 + 70000 + 90000)/3 ≈ 76667, Sales 40000 (Lata's NULL is ignored by AVG, not counted as 0), NULL group 45000. Only IT qualifies.", "difficulty": "moderate", "source": "Product-company MCQ pattern"},
  {"id":"cs-dbms-sql-22","question":"Table Emp(id, name, dept, salary, mgr) rows: (1, 'Asha', 'HR', 50000, NULL), (2, 'Ravi', 'IT', 70000, 1), (3, 'Meena', 'IT', 70000, 2), (4, 'John', 'Sales', 40000, 1), (5, 'Kiran', 'IT', 90000, 2), (6, 'Dev', NULL, 45000, 4), (7, 'Lata', 'Sales', NULL, 4).\nWhat does this query return?\n```sql\nSELECT MAX(salary) FROM Emp\nWHERE salary < (SELECT MAX(salary) FROM Emp);\n```","options":["90000","70000","Two rows: 70000 and 70000","50000"],"answer":1,"explanation":"The subquery gives 90000; the outer query takes the largest salary below it, 70000, as one value. This is the classic second-highest-salary query; duplicates do not matter because MAX returns one row.","difficulty":"moderate","source":"Amazon · Microsoft MCQ pattern"},
  {"id":"cs-dbms-sql-23","question":"Table Emp(id, name, dept, salary, mgr) rows: (1, 'Asha', 'HR', 50000, NULL), (2, 'Ravi', 'IT', 70000, 1), (3, 'Meena', 'IT', 70000, 2), (4, 'John', 'Sales', 40000, 1), (5, 'Kiran', 'IT', 90000, 2), (6, 'Dev', NULL, 45000, 4), (7, 'Lata', 'Sales', NULL, 4).\nTable Dept(dname, city) rows: ('HR', 'Pune'), ('IT', 'Delhi'), ('Ops', 'Mumbai').\nWhich names does this query return?\n```sql\nSELECT name FROM Emp\nWHERE dept NOT IN (SELECT dname FROM Dept);\n```","options":["No rows","John, Lata, Dev","John, Lata","Dev"],"answer":2,"explanation":"The subquery {HR, IT, Ops} has no NULL, so NOT IN works normally for Sales: John and Lata. Dev's dept is NULL, and NULL NOT IN (...) is UNKNOWN, so Dev is not returned.","difficulty":"hard","source":"Product-company MCQ pattern"},
  {"id": "cs-dbms-sql-24", "question": "Table Emp(id, name, dept, salary, mgr) rows: (1, 'Asha', 'HR', 50000, NULL), (2, 'Ravi', 'IT', 70000, 1), (3, 'Meena', 'IT', 70000, 2), (4, 'John', 'Sales', 40000, 1), (5, 'Kiran', 'IT', 90000, 2), (6, 'Dev', NULL, 45000, 4), (7, 'Lata', 'Sales', NULL, 4).\nWhich employees does this query return?\n```sql\nSELECT e.name\nFROM Emp e JOIN Emp m ON e.mgr = m.id\nWHERE m.dept = 'IT';\n```", "options": ["Ravi, Kiran", "Ravi, Meena, Kiran", "Meena, Kiran, Dev", "Meena, Kiran"], "answer": 3, "explanation": "This is a self-join: m is the manager. Employees whose manager is in IT: Meena and Kiran (manager Ravi, IT). Ravi himself is in IT but his manager Asha is in HR.", "difficulty": "hard", "source": "Amazon · Microsoft MCQ pattern"},
  {"id":"cs-dbms-sql-25","question":"R(A, B, C) has functional dependencies AB → C and C → B. What is the highest normal form of R?","options":["3NF but not BCNF","2NF","BCNF","1NF"],"answer":0,"explanation":"Candidate keys are AB and AC, so all attributes are prime. C → B: C is not a superkey, so BCNF fails; but B is prime, so 3NF holds. This is the textbook 3NF-but-not-BCNF shape.","difficulty":"hard","source":"Product-company MCQ pattern"},
  {"id": "cs-dbms-sql-26", "question": "R(A, B, C) with A → B and B → C. Which decomposition is lossless?", "options": ["R1(A), R2(B, C)", "R1(A, B), R2(B, C)", "R1(A, B), R2(C)", "R1(A, C), R2(B, C)"], "answer": 1, "explanation": "A binary decomposition is lossless if the common attributes functionally determine one side. (AB) ∩ (BC) = B and B → C, so B is a key of R2. In (AC, BC) the common attribute C determines nothing. Decompositions with no common attribute are lossy.", "difficulty": "hard", "source": "Product-company MCQ pattern"},
  {"id": "cs-dbms-sql-27", "question": "Is the schedule R1(A), R2(A), W1(A), W2(A) conflict serializable?", "options": ["Yes, equivalent to T1 → T2", "Yes, equivalent to T2 → T1", "Yes, because no transaction reads a dirty value", "No; the precedence graph has a cycle T1 → T2 → T1"], "answer": 3, "explanation": "R1(A) before W2(A) gives T1 → T2; R2(A) before W1(A) gives T2 → T1. A cycle means it is not conflict serializable; this is the lost-update pattern, where T1's write is overwritten.", "difficulty": "hard", "source": "Product-company MCQ pattern"},
  {"id": "cs-dbms-sql-28", "question": "Which isolation level prevents dirty reads and non-repeatable reads but may still allow phantom reads (in the SQL standard)?", "options": ["READ UNCOMMITTED", "READ COMMITTED", "REPEATABLE READ", "SERIALIZABLE"], "answer": 2, "explanation": "REPEATABLE READ keeps rows already read stable, but new rows matching a predicate can appear (phantoms). Only SERIALIZABLE forbids all three; READ COMMITTED still allows non-repeatable reads.", "difficulty": "moderate", "source": "IBM · Deloitte pattern"},
  {"id":"cs-dbms-sql-29","question":"Which statement about basic two-phase locking (2PL) is correct?","options":["It guarantees freedom from cascading rollback but not serializability","It guarantees conflict serializability and freedom from deadlock","It requires all locks to be acquired before the transaction starts","It guarantees conflict serializability but not freedom from deadlock or cascading rollback"],"answer":3,"explanation":"Growing then shrinking phases ensure conflict serializability. Two transactions can still wait on each other's locks (deadlock), and releasing locks before commit allows cascading rollbacks; strict 2PL fixes the latter, conservative 2PL the former.","difficulty":"moderate","source":"Product-company MCQ pattern"},
  {"id": "cs-dbms-sql-30", "question": "A B+ tree is built on a key of 9 bytes. A block is 1024 bytes and a block pointer is 6 bytes. What is the maximum order p (number of child pointers) of an internal node?", "options": ["68", "63", "69", "113"], "answer": 0, "explanation": "An internal node holds p pointers and p − 1 keys: 6p + 9(p − 1) ≤ 1024 → 15p ≤ 1033 → p ≤ 68.9, so p = 68. 69 comes from rounding up; 113 uses keys only.", "difficulty": "hard", "source": "Product-company MCQ pattern"},
  {"id":"cs-dbms-sql-31","question":"R(A, B, C, D) has A as its only candidate key. How many superkeys does R have?","options":["15","8","7","4"],"answer":1,"explanation":"Every superkey must contain A; each of B, C and D may be in or out: 2³ = 8 (A, AB, AC, AD, ABC, ABD, ACD, ABCD). 15 is the total number of non-empty subsets.","difficulty":"hard","source":"Product-company MCQ pattern"},
  {"id": "cs-dbms-sql-32", "question": "Table Emp(id, name, dept, salary, mgr) rows: (1, 'Asha', 'HR', 50000, NULL), (2, 'Ravi', 'IT', 70000, 1), (3, 'Meena', 'IT', 70000, 2), (4, 'John', 'Sales', 40000, 1), (5, 'Kiran', 'IT', 90000, 2), (6, 'Dev', NULL, 45000, 4), (7, 'Lata', 'Sales', NULL, 4).\nWhat does `SELECT AVG(salary) FROM Emp;` return (rounded)?", "options": ["52143", "NULL, because one salary is NULL", "60833", "70000"], "answer": 2, "explanation": "AVG ignores NULLs: (50000 + 70000 + 70000 + 40000 + 90000 + 45000) / 6 = 365000/6 ≈ 60833. Dividing by all 7 rows (treating NULL as 0) gives 52143.", "difficulty": "moderate", "source": "Product-company MCQ pattern"},
  {"id":"cs-dbms-sql-33","question":"Table Emp(id, name, dept, salary, mgr) rows: (1, 'Asha', 'HR', 50000, NULL), (2, 'Ravi', 'IT', 70000, 1), (3, 'Meena', 'IT', 70000, 2), (4, 'John', 'Sales', 40000, 1), (5, 'Kiran', 'IT', 90000, 2), (6, 'Dev', NULL, 45000, 4), (7, 'Lata', 'Sales', NULL, 4).\nFor Asha's row, what are the values of rk and drk?\n```sql\nSELECT name,\n       RANK()       OVER (ORDER BY salary DESC) AS rk,\n       DENSE_RANK() OVER (ORDER BY salary DESC) AS drk\nFROM Emp\nWHERE salary IS NOT NULL;\n```","options":["rk = 3, drk = 4","rk = 4, drk = 4","rk = 3, drk = 3","rk = 4, drk = 3"],"answer":3,"explanation":"Order: 90000 (1), 70000, 70000 (both 2), then 50000. RANK skips after a tie, so Asha gets 4; DENSE_RANK does not skip, so she gets 3.","difficulty":"hard","source":"Amazon · Microsoft MCQ pattern"},
  {"id":"cs-dbms-sql-34","question":"Table Emp(id, name, dept, salary, mgr) rows: (1, 'Asha', 'HR', 50000, NULL), (2, 'Ravi', 'IT', 70000, 1), (3, 'Meena', 'IT', 70000, 2), (4, 'John', 'Sales', 40000, 1), (5, 'Kiran', 'IT', 90000, 2), (6, 'Dev', NULL, 45000, 4), (7, 'Lata', 'Sales', NULL, 4).\nWhat does this query return?\n```sql\nSELECT COUNT(DISTINCT salary), COUNT(salary) FROM Emp;\n```","options":["5, 6","6, 6","6, 7","5, 7"],"answer":0,"explanation":"Non-NULL salaries: 50000, 70000, 70000, 40000, 90000, 45000 → COUNT = 6, distinct = 5 (70000 twice). Lata's NULL is skipped by both.","difficulty":"moderate","source":"TCS NQT · Infosys pattern"},
  {"id": "cs-dbms-sql-35", "question": "Schedule: W1(A), R2(A), C2, C1, where C means commit. Which classification is correct?", "options": ["Recoverable but not cascadeless", "Not recoverable", "Recoverable and cascadeless", "Strict"], "answer": 1, "explanation": "T2 reads A written by T1 and commits before T1 commits. If T1 now aborts, T2 has committed a value that never existed, so the schedule is not recoverable. Committing T1 first would make it recoverable (still not cascadeless).", "difficulty": "hard", "source": "Product-company MCQ pattern"},
  {"id":"cs-dbms-sql-36","question":"Under basic timestamp ordering, TS(T1) = 10 and TS(T2) = 20. T2 has read item X, so read-TS(X) = 20. T1 now issues write(X). What happens?","options":["The write is ignored under the Thomas write rule","T2 is rolled back","T1 is rolled back","The write is performed"],"answer":2,"explanation":"A write by T1 is rejected when TS(T1) < read-TS(X): a younger transaction already read the old value, so T1 is aborted and restarted. The Thomas write rule only ignores obsolete writes when a younger transaction has WRITTEN X, not read it.","difficulty":"hard","source":"Product-company MCQ pattern"},
  {"id":"cs-dbms-sql-37","question":"R(A, B, C, D, E, F) has FDs A → B, BC → D, D → E, E → C, CE → F. Which of these is NOT a candidate key?","options":["AC","AE","AD","AB"],"answer":3,"explanation":"(AB)⁺ = {A, B} only. (AC)⁺: A → B, BC → D, D → E, CE → F, all attributes. (AD)⁺: D → E → C, then B and F. (AE)⁺: E → C, then B, D, F. So AC, AD and AE are keys; AB is not.","difficulty":"hard","source":"Product-company MCQ pattern"},
  {"id": "cs-dbms-sql-38", "question": "Table Emp(id, name, dept, salary, mgr) rows: (1, 'Asha', 'HR', 50000, NULL), (2, 'Ravi', 'IT', 70000, 1), (3, 'Meena', 'IT', 70000, 2), (4, 'John', 'Sales', 40000, 1), (5, 'Kiran', 'IT', 90000, 2), (6, 'Dev', NULL, 45000, 4), (7, 'Lata', 'Sales', NULL, 4).\nWhat does this query return?\n```sql\nSELECT COUNT(*), SUM(salary), MAX(salary)\nFROM Emp WHERE dept = 'Ops';\n```", "options": ["One row: 0, NULL, NULL", "One row: 0, 0, 0", "One row: NULL, NULL, NULL", "No rows"], "answer": 0, "explanation": "An aggregate query without GROUP BY always returns exactly one row. Over an empty set, COUNT gives 0 but SUM and MAX give NULL.", "difficulty": "hard", "source": "Amazon · Microsoft MCQ pattern"},
  {"id":"cs-dbms-sql-39","question":"Which isolation-related statement is correct for the SQL standard levels?","options":["READ COMMITTED prevents non-repeatable reads","READ UNCOMMITTED allows dirty reads","SERIALIZABLE allows phantom reads","REPEATABLE READ allows dirty reads"],"answer":1,"explanation":"Each level forbids more: READ UNCOMMITTED allows all three anomalies; READ COMMITTED forbids dirty reads; REPEATABLE READ also forbids non-repeatable reads; SERIALIZABLE forbids phantoms too.","difficulty":"moderate","source":"HCL · Tech Mahindra pattern"},
  {"id":"cs-dbms-sql-40","question":"Which statement about dense and sparse indexes is correct?","options":["A primary index must always be dense","A dense index has an entry for only one record per block","A sparse index can be used only if the data file is sorted on the search key","A secondary index on a non-ordering field can be sparse"],"answer":2,"explanation":"A sparse index stores one entry per block and relies on the file being ordered on that key to find records in between. A secondary index must be dense because the file is not ordered on that field; a primary index is usually sparse.","difficulty":"moderate","source":"IBM · Deloitte pattern"},
  {"id":"cs-dbms-sql-41","question":"Table Emp(id, name, dept, salary, mgr) rows: (1, 'Asha', 'HR', 50000, NULL), (2, 'Ravi', 'IT', 70000, 1), (3, 'Meena', 'IT', 70000, 2), (4, 'John', 'Sales', 40000, 1), (5, 'Kiran', 'IT', 90000, 2), (6, 'Dev', NULL, 45000, 4), (7, 'Lata', 'Sales', NULL, 4).\nWhat is returned?\n```sql\nSELECT COUNT(*) FROM Emp WHERE salary <> 70000;\n```","options":["7","6","5","4"],"answer":3,"explanation":"Rows with salary 50000, 40000, 90000, 45000 qualify = 4. Lata's NULL salary makes NULL <> 70000 UNKNOWN, so her row is filtered out; 5 is the common wrong answer.","difficulty":"moderate","source":"Product-company MCQ pattern"},
  {"id":"cs-dbms-sql-42","question":"Which statement about view serializability is correct?","options":["Every conflict-serializable schedule is view serializable, and a schedule that is view but not conflict serializable must contain a blind write","View serializability can be tested in polynomial time with a precedence graph","Every view-serializable schedule is conflict serializable","View and conflict serializability are the same"],"answer":0,"explanation":"Conflict ⊂ view. The extra view-serializable schedules all involve blind writes (writes without a prior read). Testing view serializability is NP-complete, unlike the precedence-graph test for conflict serializability.","difficulty":"hard","source":"Product-company MCQ pattern"},
  {"id":"cs-dbms-sql-43","question":"Table Emp(id, name, dept, salary, mgr) rows: (1, 'Asha', 'HR', 50000, NULL), (2, 'Ravi', 'IT', 70000, 1), (3, 'Meena', 'IT', 70000, 2), (4, 'John', 'Sales', 40000, 1), (5, 'Kiran', 'IT', 90000, 2), (6, 'Dev', NULL, 45000, 4), (7, 'Lata', 'Sales', NULL, 4).\nThe query below is meant to list employees who manage nobody. What does it return?\n```sql\nSELECT name FROM Emp\nWHERE id NOT IN (SELECT mgr FROM Emp);\n```","options":["Meena, Kiran, Dev, Lata and Asha","No rows","Meena, Kiran, Dev, Lata","Asha only"],"answer":1,"explanation":"The subquery contains NULL (Asha's mgr). x NOT IN (…, NULL) is never TRUE: it is FALSE if x matches and UNKNOWN otherwise, so no row qualifies. Use NOT EXISTS or filter mgr IS NOT NULL to get Meena, Kiran, Dev, Lata.","difficulty":"hard","source":"Product-company MCQ pattern"},
  {"id":"cs-dbms-sql-44","question":"Table Emp(id, name, dept, salary, mgr) rows: (1, 'Asha', 'HR', 50000, NULL), (2, 'Ravi', 'IT', 70000, 1), (3, 'Meena', 'IT', 70000, 2), (4, 'John', 'Sales', 40000, 1), (5, 'Kiran', 'IT', 90000, 2), (6, 'Dev', NULL, 45000, 4), (7, 'Lata', 'Sales', NULL, 4).\nHow many rows does each query return?\n```sql\n-- Q1\nSELECT name FROM Emp e\nWHERE NOT EXISTS (SELECT 1 FROM Emp x WHERE x.mgr = e.id);\n-- Q2\nSELECT name FROM Emp\nWHERE id NOT IN (SELECT mgr FROM Emp);\n```","options":["Q1: 3, Q2: 0","Q1: 0, Q2: 4","Q1: 4, Q2: 0","Q1: 4, Q2: 4"],"answer":2,"explanation":"NOT EXISTS only asks whether a matching row exists, and NULL mgr values simply never match: Meena, Kiran, Dev, Lata = 4. NOT IN against a list containing NULL is never TRUE, so Q2 returns 0 rows.","difficulty":"hard","source":"Product-company MCQ pattern"},
  {"id": "cs-dbms-sql-45", "question": "Table Emp(id, name, dept, salary, mgr) rows: (1, 'Asha', 'HR', 50000, NULL), (2, 'Ravi', 'IT', 70000, 1), (3, 'Meena', 'IT', 70000, 2), (4, 'John', 'Sales', 40000, 1), (5, 'Kiran', 'IT', 90000, 2), (6, 'Dev', NULL, 45000, 4), (7, 'Lata', 'Sales', NULL, 4).\nWhat does this query return?\n```sql\nSELECT dept, COUNT(*) AS a, COUNT(salary) AS b\nFROM Emp\nGROUP BY dept\nHAVING COUNT(salary) < COUNT(*);\n```", "options": ["No rows", "NULL, 1, 0 and Sales, 2, 1", "NULL, 1, 1 and Sales, 2, 1", "Sales, 2, 1"], "answer": 3, "explanation": "Only Sales has a NULL salary (Lata): COUNT(*) = 2, COUNT(salary) = 1. The NULL-dept group is Dev, whose salary 45000 is not NULL, so it has 1 and 1 and fails the test.", "difficulty": "hard", "source": "Product-company MCQ pattern"},
  {"id":"cs-dbms-sql-46","question":"Table Emp(id, name, dept, salary, mgr) rows: (1, 'Asha', 'HR', 50000, NULL), (2, 'Ravi', 'IT', 70000, 1), (3, 'Meena', 'IT', 70000, 2), (4, 'John', 'Sales', 40000, 1), (5, 'Kiran', 'IT', 90000, 2), (6, 'Dev', NULL, 45000, 4), (7, 'Lata', 'Sales', NULL, 4).\nTable Dept(dname, city) rows: ('HR', 'Pune'), ('IT', 'Delhi'), ('Ops', 'Mumbai').\nHow many rows does each query return?\n```sql\n-- Q1\nSELECT e.name FROM Emp e LEFT JOIN Dept d\n  ON e.dept = d.dname\nWHERE d.city <> 'Delhi';\n-- Q2\nSELECT e.name FROM Emp e LEFT JOIN Dept d\n  ON e.dept = d.dname AND d.city <> 'Delhi';\n```","options":["Q1: 1, Q2: 7","Q1: 4, Q2: 7","Q1: 4, Q2: 4","Q1: 1, Q2: 1"],"answer":0,"explanation":"Q1: the WHERE runs after the join. Rows with city NULL (John, Lata, Dev) give UNKNOWN and IT rows give FALSE, leaving only Asha (Pune): 1 row; the outer join has become an inner join. Q2: the condition is part of ON, so every Emp row is kept (unmatched ones get NULLs): 7.","difficulty":"hard","source":"Product-company MCQ pattern"},
  {"id": "cs-dbms-sql-47", "question": "Table Emp(id, name, dept, salary, mgr) rows: (1, 'Asha', 'HR', 50000, NULL), (2, 'Ravi', 'IT', 70000, 1), (3, 'Meena', 'IT', 70000, 2), (4, 'John', 'Sales', 40000, 1), (5, 'Kiran', 'IT', 90000, 2), (6, 'Dev', NULL, 45000, 4), (7, 'Lata', 'Sales', NULL, 4).\nWhat is the value of running for Ravi (id 2)?\n```sql\nSELECT id, salary,\n       SUM(salary) OVER (ORDER BY salary) AS running\nFROM Emp\nWHERE salary IS NOT NULL;\n```", "options": ["205000", "275000", "365000", "135000"], "answer": 1, "explanation": "With ORDER BY and no frame clause, the default frame is RANGE BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW, which includes all peers with the same salary. 40000 + 45000 + 50000 + 70000 + 70000 = 275000 for both Ravi and Meena. 205000 assumes a row-by-row (ROWS) frame.", "difficulty": "hard", "source": "Amazon · Microsoft MCQ pattern"},
  {"id":"cs-dbms-sql-48","question":"Table Emp(id, name, dept, salary, mgr) rows: (1, 'Asha', 'HR', 50000, NULL), (2, 'Ravi', 'IT', 70000, 1), (3, 'Meena', 'IT', 70000, 2), (4, 'John', 'Sales', 40000, 1), (5, 'Kiran', 'IT', 90000, 2), (6, 'Dev', NULL, 45000, 4), (7, 'Lata', 'Sales', NULL, 4).\nWhat do the two queries return?\n```sql\n-- Q1\nSELECT salary FROM (\n  SELECT salary, DENSE_RANK() OVER (ORDER BY salary DESC) AS r\n  FROM Emp WHERE salary IS NOT NULL) t\nWHERE r = 3;\n-- Q2\nSELECT salary FROM (\n  SELECT salary, ROW_NUMBER() OVER (ORDER BY salary DESC) AS r\n  FROM Emp WHERE salary IS NOT NULL) t\nWHERE r = 3;\n```","options":["Q1: 45000, Q2: 70000","Q1: 50000, Q2: 50000","Q1: 50000, Q2: 70000","Q1: 70000, Q2: 50000"],"answer":2,"explanation":"Distinct salaries descending: 90000, 70000, 50000, so the 3rd highest distinct salary (DENSE_RANK = 3) is 50000. ROW_NUMBER numbers the rows 90000, 70000, 70000, …, so row 3 is the second 70000. Use DENSE_RANK for the 'nth highest salary' problem.","difficulty":"hard","source":"Amazon · Microsoft MCQ pattern"},
  {"id":"cs-dbms-sql-49","question":"Table Emp(id, name, dept, salary, mgr) rows: (1, 'Asha', 'HR', 50000, NULL), (2, 'Ravi', 'IT', 70000, 1), (3, 'Meena', 'IT', 70000, 2), (4, 'John', 'Sales', 40000, 1), (5, 'Kiran', 'IT', 90000, 2), (6, 'Dev', NULL, 45000, 4), (7, 'Lata', 'Sales', NULL, 4).\nWhich employees are returned?\n```sql\nSELECT name FROM Emp e\nWHERE salary > (SELECT AVG(salary) FROM Emp x\n                WHERE x.dept = e.dept);\n```","options":["Kiran, Ravi and Meena","Kiran and Asha","Kiran and Dev","Kiran only"],"answer":3,"explanation":"Department averages: HR 50000, IT ≈ 76667, Sales 40000 (NULL ignored). Only Kiran (90000) beats his average; Asha and John equal theirs. For Dev, x.dept = NULL matches no row, the average is NULL, and the comparison is UNKNOWN.","difficulty":"hard","source":"Product-company MCQ pattern"},
  {"id":"cs-dbms-sql-50","question":"Table Emp(id, name, dept, salary, mgr) rows: (1, 'Asha', 'HR', 50000, NULL), (2, 'Ravi', 'IT', 70000, 1), (3, 'Meena', 'IT', 70000, 2), (4, 'John', 'Sales', 40000, 1), (5, 'Kiran', 'IT', 90000, 2), (6, 'Dev', NULL, 45000, 4), (7, 'Lata', 'Sales', NULL, 4).\nTable Dept(dname, city) rows: ('HR', 'Pune'), ('IT', 'Delhi'), ('Ops', 'Mumbai').\nHow many rows does this query return?\n```sql\nSELECT *\nFROM Emp e FULL OUTER JOIN Dept d ON e.dept = d.dname;\n```","options":["8","10","7","9"],"answer":0,"explanation":"4 matched rows + 3 unmatched Emp rows (John, Lata, Dev) + 1 unmatched Dept row (Ops) = 8. Adding the two table sizes (10) double-counts matches.","difficulty":"hard","source":"Product-company MCQ pattern"},
  {"id":"cs-dbms-sql-51","question":"Table A(x) rows: (1), (1), (2), (NULL).\nTable B(x) rows: (1), (1), (1), (NULL), (3).\nHow many rows do the inner join and the left join return?\n```sql\nSELECT * FROM A JOIN B ON A.x = B.x;\nSELECT * FROM A LEFT JOIN B ON A.x = B.x;\n```","options":["6 and 7","6 and 8","7 and 8","2 and 4"],"answer":1,"explanation":"Each of A's two 1s matches B's three 1s: 2 × 3 = 6; NULLs never match each other. The left join adds A's unmatched rows 2 and NULL: 6 + 2 = 8. Counting NULL = NULL as a match gives 7.","difficulty":"hard","source":"Product-company MCQ pattern"},
  {"id":"cs-dbms-sql-52","question":"Table Emp(id, name, dept, salary, mgr) rows: (1, 'Asha', 'HR', 50000, NULL), (2, 'Ravi', 'IT', 70000, 1), (3, 'Meena', 'IT', 70000, 2), (4, 'John', 'Sales', 40000, 1), (5, 'Kiran', 'IT', 90000, 2), (6, 'Dev', NULL, 45000, 4), (7, 'Lata', 'Sales', NULL, 4).\nWhat does this query return?\n```sql\nSELECT CASE WHEN salary > 60000 THEN 'H'\n            WHEN salary <= 60000 THEN 'L'\n            ELSE 'U' END AS band,\n       COUNT(*)\nFROM Emp GROUP BY band;\n```","options":["H 3, L 3","H 4, L 3","H 3, L 3, U 1","H 3, L 4"],"answer":2,"explanation":"H: Ravi, Meena, Kiran. L: Asha, John, Dev. Lata's NULL salary fails both comparisons (UNKNOWN), so it falls to ELSE 'U'. The two WHEN conditions look exhaustive but are not when NULLs exist.","difficulty":"hard","source":"Product-company MCQ pattern"},
  {"id":"cs-dbms-sql-53","question":"Table Emp(id, name, dept, salary, mgr) rows: (1, 'Asha', 'HR', 50000, NULL), (2, 'Ravi', 'IT', 70000, 1), (3, 'Meena', 'IT', 70000, 2), (4, 'John', 'Sales', 40000, 1), (5, 'Kiran', 'IT', 90000, 2), (6, 'Dev', NULL, 45000, 4), (7, 'Lata', 'Sales', NULL, 4).\nWhat does this query return?\n```sql\nSELECT dept, MAX(salary)\nFROM Emp\nWHERE salary < 90000\nGROUP BY dept\nHAVING COUNT(*) > 1;\n```","options":["IT 70000 and Sales 40000","IT 90000","IT 70000, Sales 40000 and HR 50000","IT 70000"],"answer":3,"explanation":"WHERE runs first and drops Kiran (90000) and Lata (NULL < 90000 is UNKNOWN). Remaining groups: HR 1, IT 2 (Ravi, Meena), Sales 1 (John), NULL 1. Only IT has COUNT > 1, with MAX 70000. Sales loses Lata before grouping.","difficulty":"hard","source":"Product-company MCQ pattern"},
  {"id":"cs-dbms-sql-54","question":"Table Emp(id, name, dept, salary, mgr) rows: (1, 'Asha', 'HR', 50000, NULL), (2, 'Ravi', 'IT', 70000, 1), (3, 'Meena', 'IT', 70000, 2), (4, 'John', 'Sales', 40000, 1), (5, 'Kiran', 'IT', 90000, 2), (6, 'Dev', NULL, 45000, 4), (7, 'Lata', 'Sales', NULL, 4).\nWhat does this query return?\n```sql\nSELECT COUNT(*)\nFROM Emp a, Emp b\nWHERE a.salary < b.salary;\n```","options":["14","49","15","21"],"answer":0,"explanation":"Only the 6 non-NULL salaries can satisfy the condition. Of the C(6, 2) = 15 unordered pairs, exactly one ordering of each satisfies '<', except the tied pair (70000, 70000), which satisfies neither: 15 − 1 = 14.","difficulty":"hard","source":"Product-company MCQ pattern"},
  {"id":"cs-dbms-sql-55","question":"Table Emp(id, name, dept, salary, mgr) rows: (1, 'Asha', 'HR', 50000, NULL), (2, 'Ravi', 'IT', 70000, 1), (3, 'Meena', 'IT', 70000, 2), (4, 'John', 'Sales', 40000, 1), (5, 'Kiran', 'IT', 90000, 2), (6, 'Dev', NULL, 45000, 4), (7, 'Lata', 'Sales', NULL, 4).\nTable Dept(dname, city) rows: ('HR', 'Pune'), ('IT', 'Delhi'), ('Ops', 'Mumbai').\nWhat does this query return (SQL standard behaviour, as in PostgreSQL and SQLite)?\n```sql\nSELECT dept FROM Emp\nEXCEPT\nSELECT dname FROM Dept;\n```","options":["Sales, Sales and NULL","Sales and NULL","No rows","Sales"],"answer":1,"explanation":"EXCEPT works on distinct rows and, unlike WHERE comparisons, treats NULLs as equal to each other. Emp's distinct depts {NULL, HR, IT, Sales} minus {HR, IT, Ops} = {NULL, Sales}. Duplicates are removed, so Sales appears once.","difficulty":"hard","source":"Product-company MCQ pattern"},
  {"id":"cs-dbms-sql-56","question":"Table Emp(id, name, dept, salary, mgr) rows: (1, 'Asha', 'HR', 50000, NULL), (2, 'Ravi', 'IT', 70000, 1), (3, 'Meena', 'IT', 70000, 2), (4, 'John', 'Sales', 40000, 1), (5, 'Kiran', 'IT', 90000, 2), (6, 'Dev', NULL, 45000, 4), (7, 'Lata', 'Sales', NULL, 4).\nIn the SQL standard (and in MySQL, PostgreSQL, Oracle), what does this query return?\n```sql\nSELECT COUNT(*) FROM Emp\nWHERE salary > ALL (SELECT salary FROM Emp\n                    WHERE dept = 'Sales');\n```","options":["3","6","0","4"],"answer":2,"explanation":"The subquery returns {40000, NULL}. For any salary s > 40000, 's > ALL' becomes TRUE AND UNKNOWN = UNKNOWN; for s ≤ 40000 it is FALSE. No row gets TRUE, so the count is 0. Ignoring the NULL gives 4, the trap.","difficulty":"hard","source":"Product-company MCQ pattern"},
  {"id":"cs-dbms-sql-57","question":"Table Enroll(sid, cid) rows: (1, 'C1'), (1, 'C2'), (2, 'C1'), (3, 'C1'), (3, 'C2'), (3, 'C3'), (4, 'C3').\nTable Course(cid) rows: ('C1'), ('C2'), ('C3').\nWhat does this query return?\n```sql\nSELECT DISTINCT sid FROM Enroll e\nWHERE NOT EXISTS (\n  SELECT * FROM Course c\n  WHERE NOT EXISTS (\n    SELECT * FROM Enroll x\n    WHERE x.sid = e.sid AND x.cid = c.cid));\n```","options":["1, 2, 3 and 4","1 and 3","No rows","3"],"answer":3,"explanation":"This double NOT EXISTS is relational division: students for whom there is no course they have not taken, i.e. students enrolled in ALL courses. Only student 3 has C1, C2 and C3; student 1 lacks C3.","difficulty":"very-hard","source":"Product-company MCQ pattern"},
  {"id": "cs-dbms-sql-58", "question": "R(A, B, C, D, E) has FDs A → B, B → C, C → A, D → E. How many candidate keys does R have, and what is its highest normal form?", "options": ["3 keys; 1NF", "4 keys; 2NF", "1 key (AD); 2NF", "3 keys; 3NF"], "answer": 0, "explanation": "A, B and C determine each other in a cycle and D determines E, so the keys are AD, BD and CD. D → E is a partial dependency (D is part of every key and E is non-prime), so R is not even in 2NF.", "difficulty": "hard", "source": "Product-company MCQ pattern"},
  {"id": "cs-dbms-sql-59", "question": "R(A, B, C, D, E, F) has FDs AB → C, C → D, D → B, E → F. Which statement is correct?", "options": ["The only candidate key is ABE, and R is in 3NF", "The candidate keys are ABE, ACE and ADE, and R is in 1NF but not 2NF", "The candidate keys are AE and BE, and R is in 2NF", "The candidate keys are ABE, ACE and ADE, and R is in 3NF but not BCNF"], "answer": 1, "explanation": "A and E appear on no right side, so they are in every key; adding any one of B, C or D completes it (B, C, D form a cycle given A): ABE, ACE, ADE. E → F makes the non-prime F depend on part of a key, so 2NF fails.", "difficulty": "hard", "source": "Product-company MCQ pattern"},
  {"id": "cs-dbms-sql-60", "question": "R(A, B, C, D) has FDs AB → CD, C → A, D → B. How many candidate keys does R have, and what is its highest normal form?", "options": ["4 keys; 3NF but not BCNF", "4 keys; BCNF", "2 keys; BCNF", "3 keys; 2NF"], "answer": 0, "explanation": "Keys: AB, AD (D → B), BC (C → A) and CD. Every attribute is prime, so 3NF holds automatically. C → A and D → B have determinants that are not superkeys, so BCNF fails.", "difficulty": "very-hard", "source": "Product-company MCQ pattern"},
  {"id":"cs-dbms-sql-61","question":"R(A, B, C, D) has FDs AB → CD, C → A, D → B, giving candidate keys AB, AD, BC and CD. How many superkeys does R have?","options":["8","9","11","15"],"answer":1,"explanation":"Two-attribute superkeys are exactly the 4 keys (AC and BD are not). Every 3-attribute set contains one of them (4 sets), plus ABCD: 4 + 4 + 1 = 9. No single attribute is a superkey.","difficulty":"very-hard","source":"Product-company MCQ pattern"},
  {"id": "cs-dbms-sql-62", "question": "R(A, B, C) with AB → C and C → B is decomposed into R1(A, C) and R2(B, C) to reach BCNF. Which statement is correct?", "options": ["It is both lossless and dependency preserving", "The decomposition is lossy but dependency preserving", "The decomposition is lossless but does not preserve AB → C", "It is neither lossless nor dependency preserving"], "answer": 2, "explanation": "Common attribute C → B, so C is a key of R2 and the join is lossless. But AB → C spans both tables and cannot be checked in either one. This is why BCNF decomposition can lose dependencies while 3NF synthesis never does.", "difficulty": "hard", "source": "Product-company MCQ pattern"},
  {"id": "cs-dbms-sql-63", "question": "Schedule: R2(A), R1(B), W2(A), R3(A), W1(B), W3(A), R2(B), W2(B). Which statement is correct?", "options": ["Conflict serializable, equivalent only to T1 → T2 → T3", "Conflict serializable, equivalent to both T1 → T2 → T3 and T2 → T1 → T3", "Not conflict serializable", "Conflict serializable, equivalent only to T2 → T3 → T1"], "answer": 0, "explanation": "Conflicts on A: W2(A) before R3(A) and W3(A) → T2 → T3. Conflicts on B: R1(B) before W2(B) and W1(B) before R2(B) → T1 → T2. The graph T1 → T2 → T3 is acyclic with only one topological order.", "difficulty": "very-hard", "source": "Product-company MCQ pattern"},
  {"id": "cs-dbms-sql-64", "question": "Schedule: R1(A), W2(A), W1(A), W3(A). Which statement is correct?", "options": ["Conflict serializable but not view serializable", "Conflict serializable and view serializable", "Not conflict serializable but view serializable, equivalent to T1 → T2 → T3", "Neither conflict nor view serializable"], "answer": 2, "explanation": "R1(A) before W2(A) gives T1 → T2, and W2(A) before W1(A) gives T2 → T1: a cycle. But in serial T1, T2, T3, T1 reads the initial A and T3 writes the final A, exactly as in the schedule, so it is view serializable. W2 and W3 are blind writes.", "difficulty": "hard", "source": "Product-company MCQ pattern"},
  {"id":"cs-dbms-sql-65","question":"Classify the schedule W1(A), W2(A), C1, C2 (C = commit; T2 does not read A).","options":["Recoverable but not cascadeless","Strict","Not recoverable","Cascadeless but not strict"],"answer":3,"explanation":"No transaction reads uncommitted data, so it is cascadeless (and so recoverable). It is not strict, because T2 overwrites A before T1 has committed or aborted; strictness forbids both reading and writing an uncommitted item.","difficulty":"hard","source":"Product-company MCQ pattern"},
  {"id": "cs-dbms-sql-66", "question": "How many of the following statements are correct?\n1. Strict 2PL holds all exclusive locks until commit or abort and so avoids cascading rollbacks.\n2. Conservative (static) 2PL acquires all locks before the transaction begins and is deadlock-free.\n3. Rigorous 2PL releases shared locks early but holds exclusive locks until commit.\n4. Every schedule produced by basic 2PL is conflict serializable.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 2, "explanation": "1, 2 and 4 are correct. 3 is wrong: rigorous 2PL holds ALL locks, shared and exclusive, until commit; holding only exclusive locks is strict 2PL.", "difficulty": "hard", "source": "Product-company MCQ pattern"},
  {"id": "cs-dbms-sql-67", "question": "Deadlock prevention with timestamps: T1 (timestamp 5) is older than T2 (timestamp 10). T2 holds a lock on X and T1 requests it; separately, T1 holds a lock on Y and T2 requests it. What happens under wait-die and under wound-wait?", "options": ["Both schemes roll back the older transaction in both cases", "Wait-die: T1 waits for X, T2 is rolled back on Y. Wound-wait: T2 is rolled back on X, T2 waits for Y", "Both schemes make the younger transaction wait in both cases", "Wait-die: T1 is rolled back on X, T2 waits for Y. Wound-wait: T1 waits for X, T2 is rolled back on Y"], "answer": 1, "explanation": "Wait-die: an older requester waits, a younger requester dies. So T1 waits for X; T2 asking for Y dies. Wound-wait: an older requester wounds (rolls back) the younger holder, so T2 is rolled back for X; a younger requester waits, so T2 waits for Y. In both, only the younger transaction is ever rolled back.", "difficulty": "hard", "source": "Product-company MCQ pattern"},
  {"id": "cs-dbms-sql-68", "question": "Immediate-update recovery with a checkpoint. Log (oldest first): <T1 start>, <T1 commit>, <T2 start>, <checkpoint, active = {T2}>, <T3 start>, <T2 commit>, <T4 start>, <T3 commit>, crash. Which transactions are redone and which are undone?", "options": ["Redo T2, T3; undo T4", "Redo T1, T2, T3; undo T4", "Redo T2; undo T3, T4", "Redo T3; undo T2, T4"], "answer": 0, "explanation": "T1 committed before the checkpoint, so its changes are already on disk: ignore it. T2 and T3 committed after the checkpoint: redo. T4 never committed: undo. Redoing T1 is the common over-cautious answer.", "difficulty": "very-hard", "source": "IBM · Deloitte pattern"},
  {"id":"cs-dbms-sql-69","question":"A file of 30,000 records (100 bytes each, unspanned) is sorted on key K and stored in 1,024-byte blocks. A primary (sparse) index on K uses 15-byte entries (9-byte key + 6-byte pointer), one per data block. How many block accesses are needed to find a record by binary search on the data file, and by binary search on the index plus one data access?","options":["15 and 7","12 and 7","15 and 13","12 and 6"],"answer":1,"explanation":"Data: 1024/100 = 10 records per block, 3,000 blocks, ⌈log₂ 3000⌉ = 12 accesses. Index: 1024/15 = 68 entries per block; 3,000 entries need ⌈3000/68⌉ = 45 blocks; ⌈log₂ 45⌉ = 6, plus 1 data block = 7. 15 is ⌈log₂ 30000⌉, wrongly searching records instead of blocks.","difficulty":"very-hard","source":"Product-company MCQ pattern"},
  {"id":"cs-dbms-sql-70","question":"A B+ tree indexes 1,000,000 keys. Every leaf holds 100 keys and every internal node has 100 children, and all nodes are completely full. How many node (block) accesses are needed to fetch one record, counting the data block?","options":["5","3","4","6"],"answer":2,"explanation":"Leaves: 1,000,000/100 = 10,000. Next level: 10,000/100 = 100 nodes, then 1 root. Tree height = 3 levels (root, internal, leaf), plus 1 data block = 4. Taking log₁₀₀(10⁶) = 3 and forgetting the data block gives 3.","difficulty":"hard","source":"Product-company MCQ pattern"},
  {"id":"cs-dbms-sql-71","question":"An ER design has entity sets E1 and E2 joined by a one-to-one relationship R. Both E1 and E2 participate TOTALLY in R, and neither has a multivalued attribute. What is the minimum number of relational tables needed?","options":["2","3","4","1"],"answer":3,"explanation":"With 1:1 and total participation on both sides, every E1 entity pairs with exactly one E2 entity and vice versa, so E1, R and E2 can be merged into one table. With partial participation on one side, 2 tables are needed to avoid NULLs.","difficulty":"hard","source":"Product-company MCQ pattern"},
  {"id": "cs-dbms-sql-72", "question": "Assertion (A): In SQL, `WHERE dept = NULL` returns no rows even when dept contains NULL values.\nReason (R): A comparison with NULL using = evaluates to UNKNOWN, and WHERE keeps only rows for which the condition is TRUE.", "options": ["Both A and R are true, and R explains A", "Both A and R are true, but R does not explain A", "A is true, R is false", "A is false, R is true"], "answer": 0, "explanation": "NULL = NULL is UNKNOWN, not TRUE, so no row passes. The right test is dept IS NULL. GROUP BY, DISTINCT and set operators are the places where NULLs are treated as equal.", "difficulty": "moderate", "source": "Product-company MCQ pattern"},
  {"id": "cs-dbms-sql-73", "question": "How many of the following statements are correct?\n1. A phantom read occurs when re-running a query with the same predicate returns new rows inserted and committed by another transaction.\n2. Two-phase locking on individual rows alone is enough to prevent phantoms.\n3. Lost updates can happen under READ UNCOMMITTED.\n4. Snapshot isolation prevents dirty reads and non-repeatable reads but allows write skew.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 2, "explanation": "1, 3 and 4 are correct. 2 is false: row locks cannot lock rows that do not exist yet; preventing phantoms needs predicate, index-range (next-key) or table locks.", "difficulty": "hard", "source": "Product-company MCQ pattern"},
  {"id":"cs-dbms-sql-74","question":"Match each concept with its description:\n(P) Partial dependency  (Q) Transitive dependency  (R) BCNF violation  (S) Multivalued dependency\n(1) A non-prime attribute depends on a non-prime attribute\n(2) A determinant that is not a superkey determines a prime attribute\n(3) A non-prime attribute depends on part of a candidate key\n(4) Two independent sets of values recorded against the same key","options":["P-3, Q-1, R-2, S-4","P-3, Q-1, R-4, S-2","P-3, Q-2, R-1, S-4","P-1, Q-3, R-2, S-4"],"answer":0,"explanation":"Partial dependency breaks 2NF (3); transitive dependency breaks 3NF (1); a non-superkey determining a prime attribute passes 3NF but breaks BCNF (2); independent multi-valued facts are what 4NF removes (4).","difficulty":"moderate","source":"Accenture · Capgemini pattern"},
  {"id": "cs-dbms-sql-75", "question": "How many of the following statements about indexing are correct?\n1. A B+ tree stores data pointers only in its leaves, which are linked for range scans.\n2. A B-tree may store data pointers in internal nodes too, so a search can end above the leaf level.\n3. A hash index supports range queries such as salary BETWEEN 40000 AND 60000 efficiently.\n4. A table can have several clustered indexes as long as they are on different columns.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 1, "explanation": "Only 1 and 2 are correct. 3 is false: hashing scatters neighbouring keys, so it only helps equality lookups; range queries need an ordered structure like a B+ tree. 4 is false: rows can be physically ordered only one way, so there is at most one clustered index.", "difficulty": "hard", "source": "Product-company MCQ pattern"},
  {"id":"cs-dbms-sql-76","question":"A relation is in 2NF, but a non-key attribute depends on another non-key attribute (a transitive dependency on the key). Which normal form removes such dependencies?","options":["1NF","2NF","3NF","4NF"],"answer":2,"explanation":"3NF requires that no non-prime attribute be transitively dependent on a key. 2NF only removes partial dependencies on part of a composite key; 4NF deals with multivalued dependencies.","difficulty":"easy","source":"TCS NQT · Infosys interview pattern"},
  {"id":"cs-dbms-sql-77","question":"Which SQL command removes a table completely — its rows, its structure and its definition in the catalogue?","options":["DELETE FROM","TRUNCATE TABLE","ALTER TABLE … REMOVE","DROP TABLE"],"answer":3,"explanation":"DROP TABLE deletes the table object itself. DELETE and TRUNCATE remove rows but keep the empty table; there is no ALTER TABLE … REMOVE command.","difficulty":"easy","source":"Wipro · Cognizant technical pattern"},
  {"id":"cs-dbms-sql-78","question":"Table Orders(id, cust, city, amount) rows: (1, 'Ana', 'Pune', 500), (2, 'Ben', 'Delhi', NULL), (3, 'Ana', 'Pune', 300), (4, 'Chen', 'Delhi', 700), (5, 'Dia', NULL, 200), (6, 'Ben', 'Delhi', 700).\nWhat does this query return?\n```sql\nSELECT COUNT(*), COUNT(amount), COUNT(DISTINCT cust) FROM Orders;\n```","options":["6, 5, 4","6, 6, 4","6, 5, 6","5, 5, 4"],"answer":0,"explanation":"COUNT(*) counts all 6 rows; COUNT(amount) skips the NULL amount (5); COUNT(DISTINCT cust) counts Ana, Ben, Chen, Dia = 4. 6, 6, 4 forgets that COUNT(column) ignores NULLs.","difficulty":"moderate","source":"Accenture · Capgemini technical pattern"},
  {"id":"cs-dbms-sql-79","question":"Table Orders(id, cust, city, amount) rows: (1, 'Ana', 'Pune', 500), (2, 'Ben', 'Delhi', NULL), (3, 'Ana', 'Pune', 300), (4, 'Chen', 'Delhi', 700), (5, 'Dia', NULL, 200), (6, 'Ben', 'Delhi', 700).\nHow many rows does this query return, and what is the total shown for Delhi?\n```sql\nSELECT city, SUM(amount) FROM Orders GROUP BY city;\n```","options":["2 rows; Delhi = 1400","3 rows; Delhi = 1400","3 rows; Delhi = NULL","2 rows; Delhi = 2100"],"answer":1,"explanation":"GROUP BY puts all NULL cities into one group, so the groups are Pune, Delhi and NULL: 3 rows. SUM ignores the NULL amount in Delhi: 700 + 700 = 1400. A NULL inside a group does not make SUM NULL.","difficulty":"moderate","source":"TCS NQT · Infosys interview pattern"},
  {"id":"cs-dbms-sql-80","question":"Table Orders(id, cust, city, amount) rows: (1, 'Ana', 'Pune', 500), (2, 'Ben', 'Delhi', NULL), (3, 'Ana', 'Pune', 300), (4, 'Chen', 'Delhi', 700), (5, 'Dia', NULL, 200), (6, 'Ben', 'Delhi', 700).\nWhat does this query return?\n```sql\nSELECT AVG(amount) FROM Orders;\n```","options":["400","416.67","480","NULL"],"answer":2,"explanation":"AVG ignores NULLs: (500 + 300 + 700 + 200 + 700) / 5 = 2400 / 5 = 480. 400 divides by all 6 rows, as if the NULL were 0.","difficulty":"moderate","source":"Product-company interview pattern"},
  {"id":"cs-dbms-sql-81","question":"Transaction T1 reads a row, transaction T2 then updates that row and commits, and T1 reads the same row again and sees a different value. Which anomaly is this?","options":["Dirty read","Phantom read","Lost update","Non-repeatable read"],"answer":3,"explanation":"Reading the same row twice and getting different committed values is a non-repeatable read. A dirty read sees uncommitted data; a phantom is a new or vanished row in a range query; a lost update overwrites another transaction’s write.","difficulty":"easy","source":"Wipro · Cognizant technical pattern"},
  {"id":"cs-dbms-sql-82","question":"Table Orders(id, cust, city, amount) rows: (1, 'Ana', 'Pune', 500), (2, 'Ben', 'Delhi', NULL), (3, 'Ana', 'Pune', 300), (4, 'Chen', 'Delhi', 700), (5, 'Dia', NULL, 200), (6, 'Ben', 'Delhi', 700).\nTable Customers(name, tier) rows: ('Ana', 'Gold'), ('Ben', 'Silver'), ('Eve', 'Gold').\nHow many rows does this query return?\n```sql\nSELECT cust FROM Orders\nUNION\nSELECT name FROM Customers;\n```","options":["5","9","7","4"],"answer":0,"explanation":"UNION removes duplicates: Ana, Ben, Chen, Dia (from Orders) plus Eve (new from Customers) = 5. 9 is UNION ALL (6 + 3).","difficulty":"moderate","source":"Accenture · Capgemini technical pattern"},
  {"id":"cs-dbms-sql-83","question":"Table Orders(id, cust, city, amount) rows: (1, 'Ana', 'Pune', 500), (2, 'Ben', 'Delhi', NULL), (3, 'Ana', 'Pune', 300), (4, 'Chen', 'Delhi', 700), (5, 'Dia', NULL, 200), (6, 'Ben', 'Delhi', 700).\nWhat does this query return?\n```sql\nSELECT cust FROM Orders\nGROUP BY cust\nHAVING COUNT(*) > 1 AND SUM(amount) > 700;\n```","options":["'Ana' and 'Ben'","Only 'Ana'","Only 'Ben'","No rows"],"answer":1,"explanation":"Ana has 2 rows with sum 800 (passes). Ben has 2 rows but SUM ignores his NULL, giving 700, which is not > 700. Chen and Dia have one row each. Choosing Ben too treats the condition as ≥ 700 or the NULL as a value.","difficulty":"moderate","source":"Product-company interview pattern"},
  {"id":"cs-dbms-sql-84","question":"Table Orders(id, cust, city, amount) rows: (1, 'Ana', 'Pune', 500), (2, 'Ben', 'Delhi', NULL), (3, 'Ana', 'Pune', 300), (4, 'Chen', 'Delhi', 700), (5, 'Dia', NULL, 200), (6, 'Ben', 'Delhi', 700).\nHow many rows does this query return?\n```sql\nSELECT id FROM Orders WHERE city <> 'Pune';\n```","options":["4","2","3","6"],"answer":2,"explanation":"Rows 2, 4 and 6 (Delhi) qualify. Row 5 has city NULL, and NULL <> 'Pune' evaluates to UNKNOWN, which WHERE treats as false. 4 wrongly counts the NULL row.","difficulty":"moderate","source":"TCS NQT · Infosys interview pattern"},
  {"id":"cs-dbms-sql-85","question":"Table Orders(id, cust, city, amount) rows: (1, 'Ana', 'Pune', 500), (2, 'Ben', 'Delhi', NULL), (3, 'Ana', 'Pune', 300), (4, 'Chen', 'Delhi', 700), (5, 'Dia', NULL, 200), (6, 'Ben', 'Delhi', 700).\nWhat does this query return?\n```sql\nSELECT DISTINCT amount FROM Orders\nWHERE amount IS NOT NULL\nORDER BY amount DESC\nLIMIT 1 OFFSET 1;\n```","options":["700","300","200","500"],"answer":3,"explanation":"Distinct non-NULL amounts in descending order: 700, 500, 300, 200. OFFSET 1 skips the first, so the result is 500 — the second-highest distinct amount. Without DISTINCT the second row would be the duplicate 700.","difficulty":"moderate","source":"Wipro · Cognizant technical pattern"},
  {"id":"cs-dbms-sql-86","question":"Table Orders(id, cust, city, amount) rows: (1, 'Ana', 'Pune', 500), (2, 'Ben', 'Delhi', NULL), (3, 'Ana', 'Pune', 300), (4, 'Chen', 'Delhi', 700), (5, 'Dia', NULL, 200), (6, 'Ben', 'Delhi', 700).\nTable Customers(name, tier) rows: ('Ana', 'Gold'), ('Ben', 'Silver'), ('Eve', 'Gold').\nWhat value does this query show for 'Eve'?\n```sql\nSELECT c.name, COUNT(o.id)\nFROM Customers c LEFT JOIN Orders o ON c.name = o.cust\nGROUP BY c.name;\n```","options":["0","1","NULL","Eve does not appear"],"answer":0,"explanation":"The LEFT JOIN keeps Eve with NULLs in all Orders columns. COUNT(o.id) ignores that NULL, giving 0. COUNT(*) would have given 1, because it counts the padded row itself.","difficulty":"hard","source":"Accenture · Capgemini technical pattern"},
  {"id":"cs-dbms-sql-87","question":"R(A, B, C, D, E) has functional dependencies A → BC, CD → E and B → D. Which of the following is a candidate key?","options":["CD","A","BC","B"],"answer":1,"explanation":"A⁺: A → B, C; B → D; CD → E, so A⁺ = ABCDE and A (a single attribute) is a candidate key. CD⁺ = CDE, BC⁺ = BCDE and B⁺ = BD — none reaches A.","difficulty":"hard","source":"Product-company interview pattern"},
  {"id":"cs-dbms-sql-88","question":"Account X holds 100. T1 reads X (100); T2 reads X (100); T1 writes X = 150 and commits; T2 writes X = 80 and commits. What is the final value of X, and what is this anomaly called?","options":["150; lost update","130; dirty read","80; lost update","80; phantom read"],"answer":2,"explanation":"T2’s write was based on its stale read and overwrites T1’s committed change, leaving 80. T1’s update is lost. No uncommitted data was read, so it is not a dirty read, and no rows appear or vanish, so it is not a phantom.","difficulty":"hard","source":"TCS NQT · Infosys interview pattern"},
  {"id":"cs-dbms-sql-89","question":"Table Orders has a composite B-tree index on (city, amount). Which WHERE clause can use this index to narrow the search most effectively?","options":["WHERE amount > 500","WHERE amount = 500 OR city = 'Delhi'","WHERE UPPER(city) = 'DELHI'","WHERE city = 'Delhi' AND amount > 500"],"answer":3,"explanation":"A composite index is sorted by city first, then amount, so it serves predicates on its leftmost prefix: an equality on city plus a range on amount is ideal. amount alone skips the leading column; the OR needs both columns independently; wrapping city in a function hides it from a plain index.","difficulty":"hard","source":"Wipro · Cognizant technical pattern"},
  {"id":"cs-dbms-sql-90","question":"Which of these queries is NOT valid in standard SQL?","options":["SELECT cust, amount FROM Orders GROUP BY cust;","SELECT cust, SUM(amount) FROM Orders GROUP BY cust;","SELECT cust FROM Orders GROUP BY cust HAVING MAX(amount) > 300;","SELECT COUNT(*) FROM Orders;"],"answer":0,"explanation":"With GROUP BY, every selected column must be grouped or aggregated; amount is neither, and a group like Ana has two different amounts. (MySQL’s loose mode may accept it and pick an arbitrary value, but it is invalid in standard SQL.)","difficulty":"hard","source":"Accenture · Capgemini technical pattern"},
  {"id":"cs-dbms-sql-91","question":"Table Orders(id, cust, city, amount) rows: (1, 'Ana', 'Pune', 500), (2, 'Ben', 'Delhi', NULL), (3, 'Ana', 'Pune', 300), (4, 'Chen', 'Delhi', 700), (5, 'Dia', NULL, 200), (6, 'Ben', 'Delhi', 700).\nWhich ids does this correlated query return?\n```sql\nSELECT id FROM Orders o\nWHERE amount > (SELECT AVG(amount) FROM Orders WHERE city = o.city);\n```","options":["1 and 4","Only 1","1, 4 and 6","1 and 5"],"answer":1,"explanation":"Pune average = (500 + 300)/2 = 400, so id 1 qualifies. Delhi average ignores the NULL: (700 + 700)/2 = 700, and 700 > 700 is false. For id 5, city = NULL matches no rows, the AVG is NULL and the comparison is UNKNOWN. Only id 1. Choosing 4 and 6 averages Delhi over 3 rows (466.67).","difficulty":"hard","source":"Product-company interview pattern"},
  {"id":"cs-dbms-sql-92","question":"Table Orders(id, cust, city, amount) rows: (1, 'Ana', 'Pune', 500), (2, 'Ben', 'Delhi', NULL), (3, 'Ana', 'Pune', 300), (4, 'Chen', 'Delhi', 700), (5, 'Dia', NULL, 200), (6, 'Ben', 'Delhi', 700).\nFor the order with id 1, what are the values of r and dr?\n```sql\nSELECT id,\n       RANK()       OVER (ORDER BY amount DESC) AS r,\n       DENSE_RANK() OVER (ORDER BY amount DESC) AS dr\nFROM Orders WHERE amount IS NOT NULL;\n```","options":["r = 2, dr = 2","r = 3, dr = 3","r = 3, dr = 2","r = 2, dr = 3"],"answer":2,"explanation":"Amounts in order: 700, 700, 500, … The two 700s share rank 1. RANK leaves a gap, so 500 gets rank 3; DENSE_RANK does not, so 500 gets 2. ROW_NUMBER would give 3 as well, but without ties.","difficulty":"hard","source":"TCS NQT · Infosys interview pattern"},
  {"id":"cs-dbms-sql-93","question":"Table Orders(id, cust, city, amount) rows: (1, 'Ana', 'Pune', 500), (2, 'Ben', 'Delhi', NULL), (3, 'Ana', 'Pune', 300), (4, 'Chen', 'Delhi', 700), (5, 'Dia', NULL, 200), (6, 'Ben', 'Delhi', 700).\nWhat does this query return?\n```sql\nSELECT COUNT(*) FROM Orders\nWHERE amount > 250 OR amount <= 250;\n```","options":["6","4","0","5"],"answer":3,"explanation":"The condition looks like a tautology, but for row 2 (amount NULL) both comparisons are UNKNOWN, and UNKNOWN OR UNKNOWN is UNKNOWN, so the row is filtered out. 5 rows remain. 6 assumes two-valued logic.","difficulty":"hard","source":"Wipro · Cognizant technical pattern"},
  {"id":"cs-dbms-sql-94","question":"Table Orders(id, cust, city, amount) rows: (1, 'Ana', 'Pune', 500), (2, 'Ben', 'Delhi', NULL), (3, 'Ana', 'Pune', 300), (4, 'Chen', 'Delhi', 700), (5, 'Dia', NULL, 200), (6, 'Ben', 'Delhi', 700).\nTable Customers(name, tier) rows: ('Ana', 'Gold'), ('Ben', 'Silver'), ('Eve', 'Gold').\nHow many rows does this query return?\n```sql\nSELECT * FROM Orders o\nFULL OUTER JOIN Customers c ON c.name = o.cust;\n```","options":["7","4","9","18"],"answer":0,"explanation":"Matched pairs: Ana × 2 orders + Ben × 2 orders = 4. Unmatched Orders rows (Chen, Dia) add 2, and the unmatched customer Eve adds 1: 4 + 2 + 1 = 7. 4 is the INNER JOIN; 18 is the cross product.","difficulty":"hard","source":"Accenture · Capgemini technical pattern"},
  {"id":"cs-dbms-sql-95","question":"R(A, B, C, D) has FDs A → B and C → D. It is decomposed into R1(A, B), R2(C, D) and R3(A, C). Which statement is correct?","options":["It is lossy, because R1 and R2 share no attribute","The decomposition is lossless and dependency-preserving","It is lossless but not dependency-preserving","It is dependency-preserving but lossy"],"answer":1,"explanation":"AC is the key of R (AC⁺ = ABCD), and R3 contains it. Joining R3 with R1 on A (A → B, A is a key of R1) and then with R2 on C (C → D) is lossless at each step. A → B lives in R1 and C → D in R2, so dependencies are preserved. R1 and R2 need not share attributes because R3 links them.","difficulty":"hard","source":"Product-company interview pattern"},
  {"id":"cs-dbms-sql-96","question":"R(A, B, C, D) has exactly two candidate keys: A and BC. How many superkeys does R have?","options":["12","8","10","11"],"answer":2,"explanation":"Superkeys containing A: 2³ = 8. Containing both B and C: 2² = 4. Containing A and B and C: 2¹ = 2 (counted twice). By inclusion–exclusion 8 + 4 − 2 = 10. 12 forgets to subtract the overlap.","difficulty":"hard","source":"TCS NQT · Infosys interview pattern"},
  {"id":"cs-dbms-sql-97","question":"You need the customers who have placed no orders. Orders.cust may contain NULL values. Which query is correct in that case?","options":["SELECT name FROM Customers WHERE name NOT IN (SELECT cust FROM Orders);","SELECT c.name FROM Customers c LEFT JOIN Orders o ON o.cust = c.name WHERE o.cust IS NOT NULL;","SELECT c.name FROM Customers c JOIN Orders o ON o.cust = c.name WHERE o.id IS NULL;","SELECT name FROM Customers c WHERE NOT EXISTS (SELECT 1 FROM Orders o WHERE o.cust = c.name);"],"answer":3,"explanation":"If the subquery returns a NULL, “name NOT IN (…, NULL)” is never TRUE, so the NOT IN version returns no rows at all. NOT EXISTS is unaffected by NULLs. The LEFT JOIN version keeps only matched customers (the test is inverted), and an INNER JOIN never yields NULL ids.","difficulty":"hard","source":"Wipro · Cognizant technical pattern"},
  {"id":"cs-dbms-sql-98","question":"Table Proj(pid, lead, dept, budget, parent) rows: (1, 'Uma', 'R&D', 900, NULL), (2, 'Vik', 'R&D', 400, 1), (3, 'Uma', 'Ops', NULL, 1), (4, 'Wen', 'Ops', 400, 2), (5, 'Xia', NULL, 650, 2), (6, 'Vik', 'Ops', 250, 4), (7, 'Yash', 'R&D', NULL, NULL), (8, 'Wen', NULL, 100, 6).\nWhat values of run does this query give for pid 3, pid 7 and pid 8?\n```sql\nSELECT pid,\n       SUM(budget) OVER (PARTITION BY dept ORDER BY pid) AS run\nFROM Proj;\n```","options":["pid 3: NULL, pid 7: 1300, pid 8: 750","pid 3: NULL, pid 7: NULL, pid 8: 750","pid 3: 0, pid 7: 1300, pid 8: 750","pid 3: NULL, pid 7: 1300, pid 8: 100"],"answer":0,"explanation":"PARTITION BY puts the two NULL-dept rows (pids 5 and 8) in one partition, exactly as GROUP BY would. With ORDER BY the frame runs from the start of the partition to the current row, and SUM skips NULLs. Ops (pids 3, 4, 6): pid 3 has only its own NULL budget in the frame, so the sum is NULL, not 0. R&D (pids 1, 2, 7): at pid 7 the frame holds 900, 400 and NULL, giving 1300 - a NULL in the current row does not make the running sum NULL. NULL partition (pids 5, 8): 650, then 650 + 100 = 750.","difficulty":"very-hard","source":"Product company interview · GATE level"},
  {"id":"cs-dbms-sql-99","question":"Table Proj(pid, lead, dept, budget, parent) rows: (1, 'Uma', 'R&D', 900, NULL), (2, 'Vik', 'R&D', 400, 1), (3, 'Uma', 'Ops', NULL, 1), (4, 'Wen', 'Ops', 400, 2), (5, 'Xia', NULL, 650, 2), (6, 'Vik', 'Ops', 250, 4), (7, 'Yash', 'R&D', NULL, NULL), (8, 'Wen', NULL, 100, 6).\nHow many rows of the result have diff = NULL, and what is diff for pid 6?\n```sql\nSELECT pid,\n       budget - LAG(budget) OVER (ORDER BY pid) AS diff\nFROM Proj;\n```","options":["3 rows are NULL; pid 6 shows -400","5 rows are NULL; pid 6 shows -400","5 rows are NULL; pid 6 shows -150","1 row is NULL; pid 6 shows -400"],"answer":1,"explanation":"LAG returns the budget of the previous row in pid order, and any arithmetic with NULL is NULL. pid 1 has no previous row; pids 3 and 7 have NULL budgets themselves; pids 4 and 8 follow a row whose budget is NULL. That is 5 NULL results. LAG does not skip NULLs or look further back, so pid 6 is compared with pid 5: 250 - 650 = -400. The -150 answer compares pid 6 with pid 4, and the count of 3 forgets the rows that come right after a NULL.","difficulty":"very-hard","source":"Product company interview · GATE level"},
  {"id":"cs-dbms-sql-100","question":"Table Proj(pid, lead, dept, budget, parent) rows: (1, 'Uma', 'R&D', 900, NULL), (2, 'Vik', 'R&D', 400, 1), (3, 'Uma', 'Ops', NULL, 1), (4, 'Wen', 'Ops', 400, 2), (5, 'Xia', NULL, 650, 2), (6, 'Vik', 'Ops', 250, 4), (7, 'Yash', 'R&D', NULL, NULL), (8, 'Wen', NULL, 100, 6).\nIn the row for a.pid = 1, what are x and y?\n```sql\nSELECT a.pid, COUNT(b.pid) AS x, COUNT(c.pid) AS y\nFROM Proj a\nLEFT JOIN Proj b ON b.parent = a.pid\nLEFT JOIN Proj c ON c.parent = b.pid\nGROUP BY a.pid;\n```","options":["x = 2, y = 3","x = 2, y = 2","x = 3, y = 2","x = 3, y = 3"],"answer":2,"explanation":"Project 1 has two children (pids 2 and 3). Project 2 has two children of its own (pids 4 and 5); project 3 has none. After both joins the group for pid 1 therefore has three rows: (1, 2, 4), (1, 2, 5) and (1, 3, NULL). COUNT(b.pid) counts non-NULL b.pid values in those rows, so x = 3 - child 2 is counted twice because the second join duplicated it. COUNT(c.pid) skips the NULL, so y = 2. To count children correctly one would need COUNT(DISTINCT b.pid).","difficulty":"very-hard","source":"Product company interview · GATE level"},
  {"id":"cs-dbms-sql-101","question":"Table Proj(pid, lead, dept, budget, parent) rows: (1, 'Uma', 'R&D', 900, NULL), (2, 'Vik', 'R&D', 400, 1), (3, 'Uma', 'Ops', NULL, 1), (4, 'Wen', 'Ops', 400, 2), (5, 'Xia', NULL, 650, 2), (6, 'Vik', 'Ops', 250, 4), (7, 'Yash', 'R&D', NULL, NULL), (8, 'Wen', NULL, 100, 6).\nWhat does this query return?\n```sql\nWITH RECURSIVE up(pid, parent, budget) AS (\n  SELECT pid, parent, budget FROM Proj WHERE pid = 8\n  UNION ALL\n  SELECT p.pid, p.parent, p.budget\n  FROM Proj p JOIN up ON p.pid = up.parent)\nSELECT COUNT(*), SUM(budget) FROM up;\n```","options":["(5, 1650)","(1, 100)","(4, 1950)","(5, 2050)"],"answer":3,"explanation":"The anchor row is project 8. Each recursive step joins p.pid to the parent of a row already found, so it climbs towards the root: 8 -> 6 -> 4 -> 2 -> 1, and stops because project 1 has parent NULL, which joins to nothing. Five rows with budgets 100 + 250 + 400 + 400 + 900 = 2050. (1, 100) would be the result if the join went downwards (p.parent = up.pid), since project 8 has no children; (4, 1950) leaves out the anchor row.","difficulty":"very-hard","source":"Product company interview · GATE level"},
  {"id":"cs-dbms-sql-102","question":"Table Proj(pid, lead, dept, budget, parent) rows: (1, 'Uma', 'R&D', 900, NULL), (2, 'Vik', 'R&D', 400, 1), (3, 'Uma', 'Ops', NULL, 1), (4, 'Wen', 'Ops', 400, 2), (5, 'Xia', NULL, 650, 2), (6, 'Vik', 'Ops', 250, 4), (7, 'Yash', 'R&D', NULL, NULL), (8, 'Wen', NULL, 100, 6).\nWhich pids does this query return?\n```sql\nSELECT pid FROM Proj p\nWHERE 1 = (SELECT COUNT(DISTINCT q.budget)\n           FROM Proj q\n           WHERE q.dept = p.dept AND q.budget > p.budget);\n```","options":["pids 2 and 6","pids 2, 4 and 6","pids 2, 6 and 8","pids 1 and 4"],"answer":0,"explanation":"For each row the subquery counts the distinct budgets in the same department that are strictly larger; a count of 1 means the row holds the second-highest budget of its department. R&D has 900, 400 and NULL: pid 2 (400) has exactly one larger value. Ops has NULL, 400 and 250: pid 6 (250) has one larger value. Rows with a NULL budget or a NULL dept make the WHERE of the subquery unknown for every q, so their count is 0 and they are not returned - which is why pid 8 does not appear even though 650 > 100 among the NULL-dept rows. Pids 1 and 4 are the highest of their departments (count 0).","difficulty":"very-hard","source":"Product company interview · GATE level"},
  {"id":"cs-dbms-sql-103","question":"Table Proj(pid, lead, dept, budget, parent) rows: (1, 'Uma', 'R&D', 900, NULL), (2, 'Vik', 'R&D', 400, 1), (3, 'Uma', 'Ops', NULL, 1), (4, 'Wen', 'Ops', 400, 2), (5, 'Xia', NULL, 650, 2), (6, 'Vik', 'Ops', 250, 4), (7, 'Yash', 'R&D', NULL, NULL), (8, 'Wen', NULL, 100, 6).\nTable Team(lead, city) rows: ('Uma', 'Pune'), ('Vik', 'Goa'), ('Wen', NULL), ('Zed', 'Pune').\nHow many rows does this query return, and what is the row for 'Zed'?\n```sql\nSELECT t.lead, COUNT(p.pid), COUNT(*)\nFROM Team t\nLEFT JOIN Proj p ON p.lead = t.lead AND p.budget > 300\nGROUP BY t.lead;\n```","options":["4 rows; ('Zed', 0, 0)","4 rows; ('Zed', 0, 1)","3 rows; there is no row for 'Zed'","4 rows; ('Zed', 1, 1)"],"answer":1,"explanation":"A LEFT JOIN keeps every Team row. Zed leads no project, so he gets one row padded with NULLs: COUNT(p.pid) ignores the NULL and gives 0, but COUNT(*) counts the padded row itself and gives 1. Because the budget test is in the ON clause and not in WHERE, unmatched leads are kept rather than filtered out, so there are 4 rows (Uma, Vik and Wen each match exactly one project with budget above 300). COUNT(*) can never be 0 for a group that exists.","difficulty":"very-hard","source":"Product company interview · GATE level"},
  {"id":"cs-dbms-sql-104","question":"Table Proj(pid, lead, dept, budget, parent) rows: (1, 'Uma', 'R&D', 900, NULL), (2, 'Vik', 'R&D', 400, 1), (3, 'Uma', 'Ops', NULL, 1), (4, 'Wen', 'Ops', 400, 2), (5, 'Xia', NULL, 650, 2), (6, 'Vik', 'Ops', 250, 4), (7, 'Yash', 'R&D', NULL, NULL), (8, 'Wen', NULL, 100, 6).\nWhich rows does this query return?\n```sql\nSELECT pid FROM Proj\nWHERE NOT (dept = 'Ops' AND budget > 300);\n```","options":["4 rows: pids 1, 2, 6, 7","7 rows: every pid except 4","5 rows: pids 1, 2, 6, 7, 8","3 rows: pids 1, 2, 6"],"answer":2,"explanation":"Evaluate the AND with three-valued logic, then negate. FALSE AND anything is FALSE, so NOT gives TRUE: pids 1, 2, 7 (dept is 'R&D', even though pid 7's budget is NULL), pid 6 (budget 250 fails) and pid 8 (dept is NULL, but 100 > 300 is FALSE, so the AND is FALSE). Pid 4 makes the AND TRUE. Pid 3 (TRUE AND unknown) and pid 5 (unknown AND TRUE) give unknown, and NOT unknown is still unknown, so they are dropped. Treating NULL comparisons as simply false would return all rows except pid 4.","difficulty":"very-hard","source":"Product company interview · GATE level"},
  {"id":"cs-dbms-sql-105","question":"Table Proj(pid, lead, dept, budget, parent) rows: (1, 'Uma', 'R&D', 900, NULL), (2, 'Vik', 'R&D', 400, 1), (3, 'Uma', 'Ops', NULL, 1), (4, 'Wen', 'Ops', 400, 2), (5, 'Xia', NULL, 650, 2), (6, 'Vik', 'Ops', 250, 4), (7, 'Yash', 'R&D', NULL, NULL), (8, 'Wen', NULL, 100, 6).\nWhat does this query return?\n```sql\nSELECT lead, COUNT(CASE WHEN budget >= 400 THEN 1 END) AS big\nFROM Proj\nGROUP BY lead\nHAVING SUM(CASE WHEN dept = 'Ops' THEN budget END) IS NULL;\n```","options":["1 row: ('Uma', 1)","2 rows: ('Xia', 1), ('Yash', 0)","3 rows: ('Uma', 1), ('Xia', 1), ('Yash', 1)","3 rows: ('Uma', 1), ('Xia', 1), ('Yash', 0)"],"answer":3,"explanation":"A CASE with no ELSE yields NULL when no branch matches, and SUM over only NULLs is NULL. Uma's Ops project has a NULL budget, so her Ops sum is NULL and she qualifies; Xia and Yash have no Ops project at all, so theirs is NULL too. Vik (250) and Wen (400) have real Ops sums and are removed. COUNT counts only the rows where the CASE gives 1: Uma has 900, Xia has 650, and Yash's only budget is NULL, so his count is 0 - COUNT never returns NULL. Leaving Uma out confuses 'has an Ops project' with 'has a non-NULL Ops total'.","difficulty":"very-hard","source":"Product company interview · GATE level"},
  {"id":"cs-dbms-sql-106","question":"Table Proj(pid, lead, dept, budget, parent) rows: (1, 'Uma', 'R&D', 900, NULL), (2, 'Vik', 'R&D', 400, 1), (3, 'Uma', 'Ops', NULL, 1), (4, 'Wen', 'Ops', 400, 2), (5, 'Xia', NULL, 650, 2), (6, 'Vik', 'Ops', 250, 4), (7, 'Yash', 'R&D', NULL, NULL), (8, 'Wen', NULL, 100, 6).\nWhich pids does this query return?\n```sql\nSELECT pid FROM (\n  SELECT pid, budget,\n         AVG(budget) OVER (PARTITION BY lead) AS a\n  FROM Proj) t\nWHERE budget > a;\n```","options":["pids 2 and 4","pids 1, 2 and 4","pids 1 and 5","pids 1, 2, 4 and 5"],"answer":0,"explanation":"AVG ignores NULLs. Uma: budgets 900 and NULL, average 900, and 900 > 900 is false. Vik: 400 and 250, average 325, so pid 2 qualifies. Wen: 400 and 100, average 250, so pid 4 qualifies. Xia has one project (650 is not above its own average) and Yash's only budget is NULL. Result: pids 2 and 4. Pid 1 appears only if the NULL is wrongly counted as 0 (average 450); pids 1 and 5 are the rows above the overall average, which ignores the PARTITION BY.","difficulty":"very-hard","source":"Product company interview · GATE level"},
  {"id":"cs-dbms-sql-107","question":"Table Proj(pid, lead, dept, budget, parent) rows: (1, 'Uma', 'R&D', 900, NULL), (2, 'Vik', 'R&D', 400, 1), (3, 'Uma', 'Ops', NULL, 1), (4, 'Wen', 'Ops', 400, 2), (5, 'Xia', NULL, 650, 2), (6, 'Vik', 'Ops', 250, 4), (7, 'Yash', 'R&D', NULL, NULL), (8, 'Wen', NULL, 100, 6).\nAfter this statement runs, which rows remain in Proj?\n```sql\nDELETE FROM Proj\nWHERE budget < (SELECT AVG(budget) FROM Proj);\n```","options":["2 rows: pids 1, 5","4 rows: pids 1, 3, 5, 7","6 rows: every pid except 6 and 8","5 rows: pids 1, 2, 3, 5, 7"],"answer":1,"explanation":"The subquery is evaluated once on the table as it was before the delete: AVG ignores the two NULLs, giving (900 + 400 + 400 + 650 + 250 + 100)/6 = 450. Rows with budget below 450 are deleted: pids 2, 4, 6 and 8. For pids 3 and 7 the test NULL < 450 is unknown, so they are not deleted. Remaining: 1, 3, 5, 7. Counting the NULLs as 0 would give an average of 337.5 and delete only pids 6 and 8; assuming NULL rows are also removed leaves only pids 1 and 5.","difficulty":"very-hard","source":"Product company interview · GATE level"},
  {"id":"cs-dbms-sql-108","question":"Table Proj(pid, lead, dept, budget, parent) rows: (1, 'Uma', 'R&D', 900, NULL), (2, 'Vik', 'R&D', 400, 1), (3, 'Uma', 'Ops', NULL, 1), (4, 'Wen', 'Ops', 400, 2), (5, 'Xia', NULL, 650, 2), (6, 'Vik', 'Ops', 250, 4), (7, 'Yash', 'R&D', NULL, NULL), (8, 'Wen', NULL, 100, 6).\nWhat does this query return?\n```sql\nSELECT COUNT(*)\nFROM Proj a JOIN Proj b ON a.budget = b.budget;\n```","options":["12","6","8","10"],"answer":2,"explanation":"Each row joins with every row that has an equal budget, including itself. Budgets 900, 650, 250 and 100 occur once, giving 1 pair each. Budget 400 occurs twice (pids 2 and 4), giving 2 x 2 = 4 pairs. The two NULL budgets match nothing, not even themselves, because NULL = NULL is unknown. Total 4 + 4 = 8. The answer 6 counts each non-NULL row once; 12 lets the two NULL rows pair up with each other (another 4 pairs).","difficulty":"very-hard","source":"Product company interview · GATE level"},
  {"id":"cs-dbms-sql-109","question":"Table Proj(pid, lead, dept, budget, parent) rows: (1, 'Uma', 'R&D', 900, NULL), (2, 'Vik', 'R&D', 400, 1), (3, 'Uma', 'Ops', NULL, 1), (4, 'Wen', 'Ops', 400, 2), (5, 'Xia', NULL, 650, 2), (6, 'Vik', 'Ops', 250, 4), (7, 'Yash', 'R&D', NULL, NULL), (8, 'Wen', NULL, 100, 6).\nTable Team(lead, city) rows: ('Uma', 'Pune'), ('Vik', 'Goa'), ('Wen', NULL), ('Zed', 'Pune').\nBoth queries try to list the leads who have no R&D project. What do they return?\n```sql\n-- Q1\nSELECT t.lead FROM Team t\nLEFT JOIN Proj p ON p.lead = t.lead AND p.dept = 'R&D'\nWHERE p.pid IS NULL;\n-- Q2\nSELECT DISTINCT t.lead FROM Team t\nLEFT JOIN Proj p ON p.lead = t.lead\nWHERE p.dept <> 'R&D' OR p.pid IS NULL;\n```","options":["Q1: Wen, Zed. Q2: Zed","Q1: Wen, Zed. Q2: Wen, Zed","Q1: Zed. Q2: Uma, Vik, Wen, Zed","Q1: Wen, Zed. Q2: Uma, Vik, Wen, Zed"],"answer":3,"explanation":"Q1 joins each lead only to their R&D projects; a lead with none gets a NULL-padded row, which the IS NULL test keeps. Uma and Vik each lead an R&D project, so Q1 returns Wen and Zed - the correct anti-join. Q2 joins to all projects and then keeps any row whose dept differs from 'R&D'. Uma and Vik each also lead an Ops project, so they pass that row-level test and are listed even though they do have R&D work. Wen appears through the Ops project (pid 4); Wen's NULL-dept project fails the <> test but that does not matter. Q2 therefore returns all four leads.","difficulty":"very-hard","source":"Product company interview · GATE level"},
  {"id":"cs-dbms-sql-110","question":"Table Proj(pid, lead, dept, budget, parent) rows: (1, 'Uma', 'R&D', 900, NULL), (2, 'Vik', 'R&D', 400, 1), (3, 'Uma', 'Ops', NULL, 1), (4, 'Wen', 'Ops', 400, 2), (5, 'Xia', NULL, 650, 2), (6, 'Vik', 'Ops', 250, 4), (7, 'Yash', 'R&D', NULL, NULL), (8, 'Wen', NULL, 100, 6).\nWhat does this query return under standard SQL semantics?\n```sql\nSELECT COUNT(*) FROM Proj\nWHERE budget > ALL (SELECT budget FROM Proj WHERE dept = 'HR');\n```","options":["8","6","0","The query fails with an error"],"answer":0,"explanation":"No project belongs to 'HR', so the subquery returns an empty set. A comparison with ALL over an empty set is TRUE for every row - there is no value that could make it fail - and this holds even for the two rows whose budget is NULL, because no comparison is ever carried out. All 8 rows are counted. The answer 6 assumes the NULL budgets drop out; 0 would be the result of > ANY, which is FALSE over an empty set.","difficulty":"very-hard","source":"Product company interview · GATE level"},
  {"id":"cs-dbms-sql-111","question":"Table Proj(pid, lead, dept, budget, parent) rows: (1, 'Uma', 'R&D', 900, NULL), (2, 'Vik', 'R&D', 400, 1), (3, 'Uma', 'Ops', NULL, 1), (4, 'Wen', 'Ops', 400, 2), (5, 'Xia', NULL, 650, 2), (6, 'Vik', 'Ops', 250, 4), (7, 'Yash', 'R&D', NULL, NULL), (8, 'Wen', NULL, 100, 6).\nWhat does this query return?\n```sql\nSELECT COUNT(DISTINCT dept), COUNT(*)\nFROM (SELECT dept FROM Proj GROUP BY dept) g;\n```","options":["(3, 3)","(2, 3)","(2, 2)","(2, 8)"],"answer":1,"explanation":"GROUP BY treats all NULL depts as one group, so the inner query returns three rows: 'R&D', 'Ops' and NULL. COUNT(*) counts rows and gives 3. COUNT(DISTINCT dept) ignores NULL and gives 2. So NULLs are 'equal' for grouping but invisible to COUNT(column) - both rules apply in the same query.","difficulty":"very-hard","source":"Product company interview · GATE level"},
  {"id":"cs-dbms-sql-112","question":"R(A, B, C, D, E, F) has functional dependencies AB → C, C → A, C → D, D → B and E → F. How many candidate keys does R have, and what is its highest normal form?","options":["2 candidate keys; 1NF","3 candidate keys; 2NF","3 candidate keys; 1NF","1 candidate key; 3NF"],"answer":2,"explanation":"E appears on no right-hand side, so every key contains E, and E alone gives only {E, F}. CE: C gives A and D, D gives B, E gives F - a key. ABE: AB gives C, then D, and E gives F - a key. ADE: D gives B, then AB gives C - a key. No other minimal set works (BE, DE and AE do not reach C), so there are 3 keys: CE, ABE, ADE. F is the only non-prime attribute and E → F makes it depend on a proper part of every key, a partial dependency. So R is not in 2NF and its highest normal form is 1NF.","difficulty":"very-hard","source":"Product company interview · GATE level"},
  {"id":"cs-dbms-sql-113","question":"R(A, B, C, D, E) has functional dependencies AB → C, C → D, D → E and E → A. Which statement is correct?","options":["4 candidate keys; R is in 3NF but not BCNF, and only one of the given FDs violates BCNF","4 candidate keys; R is in BCNF","1 candidate key (AB); R is in 2NF but not 3NF","4 candidate keys; R is in 3NF but not BCNF, and three of the given FDs violate BCNF"],"answer":3,"explanation":"B is on no right-hand side, so every key contains B. AB gives C, D, E: a key. BC gives D, E, A: a key. BD gives E, A, C: a key. BE gives A, C, D: a key. With keys AB, BC, BD and BE every attribute is prime, so no FD can break 3NF. For BCNF every determinant must be a superkey: AB is, but C, D and E alone are not, so C → D, D → E and E → A all violate BCNF. Stopping at the first key AB makes C → D look like a transitive dependency of a non-prime attribute, which is the trap behind the 2NF answer.","difficulty":"very-hard","source":"Product company interview · GATE level"},
  {"id":"cs-dbms-sql-114","question":"The set F = { A → B, BC → D, AC → D, D → E, CE → A } holds on R(A, B, C, D, E). Which of the following dependencies is redundant, i.e. can be removed from F without changing its closure?","options":["AC → D","BC → D","D → E","CE → A"],"answer":0,"explanation":"An FD X → Y is redundant if Y is in the closure of X computed from the other FDs. Without AC → D: {A, C}+ gains B (A → B) and then D (BC → D), so AC → D is still implied and can be dropped. Without BC → D: {B, C}+ = {B, C} only. Without D → E: {D}+ = {D}. Without CE → A: {C, E}+ = {C, E}. So only AC → D is redundant; the others each carry information nothing else supplies.","difficulty":"very-hard","source":"Product company interview · GATE level"},
  {"id":"cs-dbms-sql-115","question":"R(A, B, C, D) with functional dependencies A → B, B → C and C → D is decomposed into R1(A, B), R2(B, C) and R3(A, D). Which statement about this decomposition is correct?","options":["It is lossless and dependency preserving","It is lossless but not dependency preserving","It is lossy but dependency preserving","It is lossy and not dependency preserving"],"answer":1,"explanation":"Lossless: R1 and R3 share A, and A is a key of both, so joining them gives (A, B, D) without spurious tuples; that result shares B with R2, and B → C makes B a key of R2, so the second join is lossless too. Dependency preservation: A → B is in R1 and B → C in R2, but C and D never appear together. R3 only carries A → D, and from A → B, B → C and A → D one cannot derive C → D (the closure of C is just {C}). So C → D can be checked only by joining, and the decomposition is not dependency preserving.","difficulty":"very-hard","source":"Product company interview · GATE level"},
  {"id":"cs-dbms-sql-116","question":"R(A, B, C, D, E) has functional dependencies A → B, BC → D, D → AE and E → C. How many of the following dependencies are logically implied?\n1. AC → E\n2. B → C\n3. BE → A\n4. D → B","options":["4","2","3","1"],"answer":2,"explanation":"Use attribute closures. {A, C}+: A gives B, BC gives D, D gives A and E - so AC → E holds. {B}+ = {B}: nothing fires, so B → C does not hold. {B, E}+: E gives C, BC gives D, D gives A - so BE → A holds. {D}+: D gives A and E, A gives B - so D → B holds. Three of the four are implied; only statement 2 fails.","difficulty":"very-hard","source":"Product company interview · GATE level"},
  {"id":"cs-dbms-sql-117","question":"A relation r(A, B, C, D) currently holds exactly these five tuples:\n(1, 2, 3, 4)\n(1, 2, 5, 6)\n(2, 2, 3, 4)\n(3, 4, 5, 4)\n(3, 4, 3, 6)\nHow many of the dependencies A → B, B → C, AC → D, BD → A, CD → B and D → C are satisfied by this instance?","options":["5","2","4","3"],"answer":3,"explanation":"An FD X → Y is violated when two tuples agree on X but differ on Y. A → B holds (1 → 2, 2 → 2, 3 → 4). B → C fails: B = 2 goes with C = 3 and C = 5. AC → D holds: the pairs (1,3), (1,5), (2,3), (3,5), (3,3) are all different. BD → A fails: tuples 1 and 3 share (B, D) = (2, 4) but have A = 1 and A = 2. CD → B holds: (3,4) → 2 twice, and (5,6), (5,4), (3,6) occur once each. D → C fails: D = 4 goes with C = 3 and C = 5. So A → B, AC → D and CD → B are satisfied: 3.","difficulty":"very-hard","source":"Product company interview · GATE level"},
  {"id":"cs-dbms-sql-118","question":"Consider the schedule R2(A); R3(B); W1(A); R2(C); W1(C); W2(B); R4(A); W4(C). Which statement is correct?","options":["It is conflict serializable, and the only equivalent serial order is T3, T2, T1, T4","It is conflict serializable, and the only equivalent serial order is T2, T3, T1, T4","It is conflict serializable, and both T3, T2, T1, T4 and T2, T3, T1, T4 are equivalent serial orders","It is not conflict serializable"],"answer":0,"explanation":"Precedence edges: R2(A) before W1(A) gives T2 → T1. R3(B) before W2(B) gives T3 → T2. R2(C) before W1(C) gives T2 → T1 again. W1(A) before R4(A) gives T1 → T4, and R2(C), W1(C) before W4(C) give T2 → T4 and T1 → T4. The graph T3 → T2 → T1 → T4 (plus T2 → T4) has no cycle, so the schedule is conflict serializable, and its only topological order is T3, T2, T1, T4. T2 cannot come before T3 because T3 read B before T2 overwrote it.","difficulty":"very-hard","source":"Product company interview · GATE level"},
  {"id":"cs-dbms-sql-119","question":"Consider the schedule R1(A); W2(A); W2(B); W1(A); W1(B); W3(A); W3(B). Which statement is correct?","options":["It is conflict serializable, equivalent to the serial order T1, T2, T3","It is not conflict serializable, but it is view serializable, equivalent only to the serial order T1, T2, T3","It is not conflict serializable, but it is view serializable, equivalent to both T1, T2, T3 and T2, T1, T3","It is neither conflict serializable nor view serializable"],"answer":1,"explanation":"R1(A) before W2(A) gives T1 → T2, while W2(A) before W1(A) gives T2 → T1: a cycle, so the schedule is not conflict serializable. For view equivalence only three things matter: T1's read of A must see the initial value, and the final writes of A and B must both come from T3. The serial order T1, T2, T3 satisfies all three. In T2, T1, T3 the read R1(A) would see T2's value instead of the initial one, so that order is not view equivalent, and any order with T3 not last changes the final writes. The writes of T2 and T1 are overwritten by T3's blind writes, which is what makes view serializability possible here.","difficulty":"very-hard","source":"Product company interview · GATE level"},
  {"id":"cs-dbms-sql-120","question":"T1 executes R1(A); W1(A); R1(B) and T2 executes R2(B); W2(B); R2(A). Of the 20 possible interleavings of these two transactions (including the two serial ones), how many are conflict serializable?","options":["10","2","8","12"],"answer":2,"explanation":"The only conflicting pairs are W1(A) with R2(A) and R1(B) with W2(B). The schedule is equivalent to T1, T2 only if W1(A) precedes R2(A) and R1(B) precedes W2(B). The second condition forces all of T1 before W2(B), so only R2(B) is free to sit in any of 4 positions among T1's three operations: 4 schedules. By symmetry, equivalence to T2, T1 needs W2(B) before R1(B) and R2(A) before W1(A), leaving only R1(A) free: 4 more. Every other interleaving has edges in both directions. Total 8, not just the 2 serial schedules.","difficulty":"very-hard","source":"Product company interview · GATE level"},
  {"id":"cs-dbms-sql-121","question":"No transaction has committed yet in the schedule W1(A); R2(A); W2(B); R3(B); W4(B); R5(B). T1 now aborts. Besides T1, which transactions must be rolled back?","options":["T2, T3 and T5","T2 only","T2, T3, T4 and T5","T2 and T3"],"answer":3,"explanation":"A transaction must be rolled back if it read a value written by a transaction that is being rolled back. T2 read A from T1, so T2 goes. T3 read B from T2, so T3 goes as well - a cascade. T4 only wrote B without reading anything, so it depends on no one, and T5 read B after T4's write, so it saw T4's value, not T2's. T4 and T5 survive. Rolling back T5 confuses 'read the item B' with 'read T2's version of B'.","difficulty":"very-hard","source":"Product company interview · GATE level"},
  {"id":"cs-dbms-sql-122","question":"A lock manager grants a request whenever it is compatible with the locks currently held; otherwise the requester waits. The requests arrive in this order: T1 exclusive on A (granted); T2 exclusive on B (granted); T3 shared on C (granted); T1 shared on B; T2 exclusive on C; T4 shared on C; T3 exclusive on A; T4 shared on A. Which statement about the resulting wait-for graph is correct?","options":["It has two cycles; aborting T3 alone does not clear the deadlock, but aborting T2 alone does","It has one cycle, T1 → T2 → T3 → T1; aborting any one of these three clears the deadlock","It has two cycles; aborting T4 alone clears the deadlock","It has no cycle, because T4's shared lock on C is compatible with T3's"],"answer":0,"explanation":"T1 waits for T2 (B). T2's exclusive request on C conflicts with T3's shared lock, so T2 waits for T3. T4's shared request on C is compatible with the lock actually held (T3's shared lock), so it is granted - and now T2 waits for T4 as well. T3 waits for T1 (A) and T4 waits for T1 (A). Edges: T1 → T2, T2 → T3, T2 → T4, T3 → T1, T4 → T1, giving the cycles T1 → T2 → T3 → T1 and T1 → T2 → T4 → T1. Aborting T3 or T4 breaks only one cycle; aborting T1 or T2, which lie on both, clears the deadlock.","difficulty":"very-hard","source":"Product company interview · GATE level"},
  {"id":"cs-dbms-sql-123","question":"Transactions T1, T2 and T3 have timestamps 1, 2 and 3. All read and write timestamps of items A and C are initially 0, and the operations arrive in this order: R3(A); W2(C); W1(C); W2(A). Which transactions are rolled back under basic timestamp ordering, and which under timestamp ordering with Thomas's write rule?","options":["Basic: T1 and T2. With Thomas's write rule: T1 and T2","Basic: T1 and T2. With Thomas's write rule: T2 only","Basic: T1 only. With Thomas's write rule: none","Basic: T2 only. With Thomas's write rule: T2 only"],"answer":1,"explanation":"R3(A) sets read-TS(A) = 3. W2(C) sets write-TS(C) = 2. W1(C): T1's timestamp 1 is below write-TS(C) = 2 while read-TS(C) = 0, so it is an obsolete write - basic timestamp ordering rolls T1 back, but Thomas's write rule simply ignores the write and lets T1 continue. W2(A): T2's timestamp 2 is below read-TS(A) = 3, meaning a younger transaction has already read A; this write must be rejected and T2 rolled back under both schemes. Thomas's rule only forgives writes that are too late relative to another write, never relative to a read.","difficulty":"very-hard","source":"Product company interview · GATE level"},
  {"id":"cs-dbms-sql-124","question":"A B+ tree uses 4096-byte blocks, 12-byte search keys, 8-byte block pointers and 10-byte record pointers. An internal node with p child pointers stores p - 1 keys; a leaf stores n (key, record pointer) pairs plus one block pointer to the next leaf. What are the largest possible p and n?","options":["p = 205, n = 186","p = 204, n = 186","p = 205, n = 185","p = 341, n = 185"],"answer":2,"explanation":"Internal node: 8p + 12(p - 1) ≤ 4096 gives 20p ≤ 4108, so p = 205 (205 pointers and 204 keys use 4088 bytes). Leaf: 22n + 8 ≤ 4096 gives n ≤ 185.8, so n = 185 (4078 bytes); 186 pairs would need 4100 bytes once the next-leaf pointer is included. Forgetting that pointer gives n = 186, forgetting the '- 1' on the keys gives p = 204, and p = 341 counts only the 12-byte keys.","difficulty":"very-hard","source":"Product company interview · GATE level"},
  {"id":"cs-dbms-sql-125","question":"A B+ tree holds 10,000 keys in its leaves. A leaf holds at most 20 and at least 10 keys; an internal node has at most 30 and at least 15 children; the root, when it is not a leaf, has at least 2 children. What are the minimum and the maximum possible number of levels (counting the root level and the leaf level)?","options":["Minimum 3, maximum 5","Minimum 3, maximum 3","Minimum 4, maximum 4","Minimum 3, maximum 4"],"answer":3,"explanation":"Fewest levels: pack every node. 10,000/20 = 500 leaves, 500/30 → 17 internal nodes, and one root over those 17: 3 levels (two levels could hold only 30 x 20 = 600 keys). Most levels: fill every node as little as allowed. A tree with h levels needs at least 2 x 15^(h-2) x 10 keys: h = 4 needs 2 x 225 x 10 = 4,500, which 10,000 keys can supply (for example 1,000 leaves, 66 nodes, 4 nodes, root), but h = 5 needs 67,500. So between 3 and 4 levels.","difficulty":"very-hard","source":"Product company interview · GATE level"},
  {"id":"cs-dbms-sql-126","question":"A file has 200,000 fixed-length records of 200 bytes stored unspanned in 1024-byte blocks. A secondary index is built on a non-ordering key field: each index entry is a 12-byte key plus an 8-byte pointer, and the index is made multilevel until the top level fits in one block. How many index levels are there, and how many block accesses does it take to fetch a record by this key?","options":["4 levels; 5 block accesses","3 levels; 4 block accesses","4 levels; 4 block accesses","1 level; 13 block accesses"],"answer":0,"explanation":"A secondary index on a non-ordering field must be dense: one entry per record, 200,000 entries. Each block holds floor(1024/20) = 51 entries. Level 1: ceil(200,000/51) = 3,922 blocks. Level 2: ceil(3,922/51) = 77 blocks. Level 3: ceil(77/51) = 2 blocks. Level 4: 1 block. A search reads one block per level and then the data block: 4 + 1 = 5 accesses. The 3-level answer builds a sparse index with one entry per data block (40,000 entries), which is possible only on the ordering field. Binary search on level 1 alone would cost ceil(log2 3,922) + 1 = 13 accesses.","difficulty":"very-hard","source":"Product company interview · GATE level"},
  {"id":"cs-dbms-sql-127","question":"Relations R (1000 blocks) and S (200 blocks) are joined with a block nested-loop join using M = 52 buffer blocks: M - 2 blocks hold a chunk of the outer relation, one block scans the inner relation and one collects output. The cost in block reads is b(outer) + ceil(b(outer)/(M - 2)) x b(inner). What is the cheapest cost obtainable by choosing the outer relation well?","options":["5000 block reads","4200 block reads","200,200 block reads","1200 block reads"],"answer":1,"explanation":"With S as the outer relation: 200 + ceil(200/50) x 1000 = 200 + 4 x 1000 = 4200. With R as the outer relation: 1000 + ceil(1000/50) x 200 = 1000 + 20 x 200 = 5000. The smaller relation should be the outer one because it needs fewer passes over the inner relation. 200,200 is the cost with only one buffer block for the outer relation (200 + 200 x 1000); 1200 would need the whole of S to fit in memory at once.","difficulty":"very-hard","source":"Product company interview · GATE level"},
];

export default questions;
